// Remove V1 browser-only data; authenticated data is never persisted here.
try{localStorage.removeItem('mrhub')}catch{}
let S={viewer:'',profiles:{},tasks:[],posts:[],requests:[],events:[],lists:[],dance:[],notes:[],activity:[],streak:0,points:0};const save=()=>{};const adult=v=>v==='Dad'||v==='Mom';const visible=t=>t.visibility==='Family'||(t.visibility==='Adults'&&adult(S.viewer))||(t.visibility==='Assigned'&&(t.who===S.viewer||t.who==='Everyone'))||(t.visibility==='Me'&&t.creator===S.viewer);const displayName=id=>S.profiles?.[id]?.displayName||id;const displayAssignee=id=>id? id==='Everyone'?'Everyone':displayName(id):'Unassigned';const visibilityName=id=>({Family:'Family / Everyone',Adults:'Adults Only',Assigned:'Assigned Person',Me:'Me Only'}[id]||id);function displayReply(r){if(!r.reply)return '';const old=r.reply.match(/^(Dad|Mom|Daughter):\s*/);const by=r.replyBy||old?.[1];return by?`${displayName(by)}: ${old?r.reply.slice(old[0].length):r.reply}`:r.reply}function nav(){let daughter=S.viewer==='Daughter';return `<div class=nav><div class=navin>${[['home','🏠','Home'],['tasks','✅',daughter?'My Stuff':'Tasks'],['dance','💃','Dance'],[daughter?'ask':'board',daughter?'🙋':'📣',daughter?'Ask':'Board'],['family','👨‍👩‍👧','Family']].map(x=>`<button onclick="render('${x[0]}')" class="${page===x[0]?'active':''}"><span class=e>${x[1]}</span>${x[2]}</button>`).join('')}</div></div>`}let page='home';function renderTopBar(){return `<div class=top><div><div class=brand>✨ Martin-Riley Family Hub</div><div class=sub>Our little corner of the world · <span id=syncStatus>Connected</span></div></div><button class=btn onclick="logout()">Sign out<br><small>${displayName(S.viewer)}</small></button></div>`}
const taskFilterState={status:'Open',assignee:'All',priority:'All',category:'All'};
let editingTaskId=null;
function openAdd(){editingTaskId=null;openTaskForm()}
const taskById=id=>S.tasks.find(t=>t.id===Number(id));
function taskOverdue(t){if(t.status!=='open'||!t.dueDate)return false;const [year,month,day]=t.dueDate.split('-').map(Number),[hour,minute]=String(t.dueTime||'23:59').split(':').map(Number);const due=new Date(year,month-1,day,hour,minute);return !Number.isNaN(due.valueOf())&&due.valueOf()<Date.now()}
function taskAwaitingAcknowledgement(t){if(!t.ack)return false;const people=t.who==='Everyone'?['Dad','Mom','Daughter']:t.who?[t.who]:[t.creator];return people.some(person=>person&&!(t.acked||[]).includes(person))}
function taskStatus(t){if(t.status==='done')return 'Completed';if(t.status==='missed')return 'Not Completed';const required=t.who&&t.who!=='Everyone'?t.who:S.viewer;if(t.ack&&!(t.acked||[]).includes(required))return 'Needs Acknowledgement';if(taskOverdue(t))return 'Overdue';return 'To Do'}
function timeLabel(value){if(!value)return 'Not recorded';const date=new Date(value);if(Number.isNaN(date.valueOf()))return value;const seconds=Math.floor((Date.now()-date.valueOf())/1000);const relative=seconds<60?'just now':seconds<3600?`${Math.floor(seconds/60)}m ago`:seconds<86400?`${Math.floor(seconds/3600)}h ago`:seconds<604800?`${Math.floor(seconds/86400)}d ago`:'';return relative?`${relative} · ${date.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}`:date.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function activityList(events){return events.map(e=>`<div class="activity-row"><b>${e.summary||e}</b>${e.createdAt?`<time>${timeLabel(e.createdAt)}</time>`:''}</div>`).join('')||'<div class=card>No recent family activity.</div>'}
function canManageTask(t){return adult(S.viewer)&&(t.creator===S.viewer||t.visibility!=='Me')}
function canCompleteTask(t){if(!t.ack)return true;const required=t.who&&t.who!=='Everyone'?t.who:t.who==='Everyone'?S.viewer:t.creator;return !!required&&(t.acked||[]).includes(required)}
function home(){const daughter=S.viewer==='Daughter',open=S.tasks.filter(t=>t.status==='open'),recent=Date.now()-7*86400000,recentlyCompleted=S.tasks.filter(t=>t.status==='done'&&Date.parse(t.completedAt||'')>=recent).length,awaiting=open.filter(t=>taskAwaitingAcknowledgement(t)).length,overdue=open.filter(taskOverdue).length,attention=open.filter(t=>taskOverdue(t)||taskAwaitingAcknowledgement(t)||['Urgent','High','High Priority'].includes(t.priority)).length;return `${renderTopBar()}<div class=hero><h1>${daughter?'🌈 Hey! Ready for a great day?':'☀️ Welcome back, '+displayName(S.viewer)+'!'}</h1><div>${daughter?`🔥 ${S.streak}-day chore streak • 🏆 ${S.points} completed chores`:`${S.requests.filter(r=>r.status==='Pending').length} request waiting`}</div></div>${daughter?'':`<div class="quick-add"><button class="btn primary" onclick="openAdd()">+ Task</button><button class=btn onclick="openItem('events')">+ Event</button><button class=btn onclick="openItem('lists')">+ List Item</button><button class=btn onclick="openItem('private')">+ Note</button></div><div class="summary-grid"><div class="summary-item"><b>${open.length}</b><span>Open</span></div><div class="summary-item"><b>${attention}</b><span>Needs Attention</span></div><div class="summary-item"><b>${awaiting}</b><span>Awaiting Acknowledgement</span></div><div class="summary-item"><b>${overdue}</b><span>Overdue</span></div><div class="summary-item"><b>${recentlyCompleted}</b><span>Recently Completed</span></div></div>`}<div class=grid>${(daughter?[['✅','My Stuff','tasks'],['💃','Dance','dance'],['🙋',`Ask ${displayName('Dad')} & ${displayName('Mom')}`,'ask'],['📣','Family Board','board'],['📅','My Calendar','calendar'],['🌙','Tomorrow Prep','tomorrow'],['🛒','Shared Lists','lists'],['💌','Me Only','private'],['🔔','Reminders','reminders']]:[['🚨','Needs Attention','tasks'],['🙋','Requests','requests'],['📣','Family Board','board'],['📅','Calendar','calendar'],['💃','Dance Hub','dance'],['🌙','Tomorrow Prep','tomorrow'],['📊','Weekly Recap','recap'],['🔐','Privacy','privacy'],['🛒','Shared Lists','lists'],['🔒','Adult Vault','vault'],['💌','Me Only','private'],['🔔','Reminders','reminders']]).map(x=>`<button class="card tile" onclick="render('${x[2]}')"><span class=emoji>${x[0]}</span><b>${x[1]}</b></button>`).join('')}</div>${daughter?`<div class=card>🏅 ${S.points>=10?'Teamwork superstar':S.points>=1?'First win earned!':'Your first achievement is waiting'} · Complete chores to celebrate!</div><div class=section><h2>🌟 Family Chore Board</h2></div>${choreBoard()}<div class=section><h2>Family Activity</h2></div>${activityList(S.activity.slice(0,8))}`:`<div class=section><h2>Today</h2></div>${taskList(open.filter(t=>visible(t)).slice(0,4))}<div class=section><h2>Recent Activity</h2></div>${activityList(S.activity.slice(0,8))}`}`}
function taskList(arr){return arr.map(t=>{const status=taskStatus(t);return `<div class="card task task-card ${status.toLowerCase().replaceAll(' ','-')}" role=button tabindex=0 onclick="openTaskDetails(${t.id})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openTaskDetails(${t.id})}"><div class=status-icon>${status==='Completed'?'✅':status==='Not Completed'?'❌':status==='Needs Acknowledgement'?'👀':status==='Overdue'?'⚠️':'⏳'}</div><div class=grow><span class="pill ${t.priority==='Urgent'?'urgent':t.priority==='High'||t.priority==='High Priority'?'high':t.priority==='Important'?'important':''}">${t.priority==='Urgent'?'🚨':t.priority==='High'||t.priority==='High Priority'?'🔴':t.priority==='Important'?'⭐':'•'} ${t.priority}</span><h3>${t.title}</h3>${t.description?`<p>${t.description}</p>`:''}<div class=meta>${displayAssignee(t.who)} • ${visibilityName(t.visibility)}${t.dueDate?' • Due '+t.dueDate:''}${t.dueTime?' at '+t.dueTime:''}${t.category?' • '+t.category:''}${t.repeat&&t.repeat!=='One Time'?' • '+t.repeat:''}</div>${t.status==='done'?`<div class=meta>Completed by ${displayName(t.completedBy)} · ${timeLabel(t.completedAt)}</div>`:''}${t.status==='missed'?`<div class=meta>${t.reason}</div>`:''}<div class=actions>${t.ack&&t.status==='open'&&!(t.acked||[]).includes(S.viewer)&&(t.who===S.viewer||t.who==='Everyone')?`<button class="btn primary" onclick="event.stopPropagation();ack(${t.id})">Acknowledge</button>`:''}${(t.who===S.viewer||t.who==='Everyone')&&t.status==='open'?`<button class="btn good" ${canCompleteTask(t)?'':'disabled'} onclick="event.stopPropagation();done(${t.id})">Complete</button><button class="btn bad" onclick="event.stopPropagation();openMissReason(${t.id},false)">Not complete</button>`:''}</div></div></div>`}).join('')||'<div class=card>🎉 Nothing here right now.</div>'}
function choreBoard(){return taskList(S.tasks.filter(t=>t.visibility==='Family'&&t.status==='open'))}
function taskFilters(){if(!adult(S.viewer))return '';return `<div class="task-filters"><label>Status<select onchange="setTaskFilter('status',this.value)">${['Open','Completed','Not Completed','All'].map(v=>`<option ${taskFilterState.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Assigned<select onchange="setTaskFilter('assignee',this.value)">${[['All','All people'],['Dad',displayName('Dad')],['Mom',displayName('Mom')],['Daughter',displayName('Daughter')],['Everyone','Everyone'],['','Unassigned']].map(([v,l])=>`<option value="${v}" ${taskFilterState.assignee===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Priority<select onchange="setTaskFilter('priority',this.value)">${['All',...['Normal','Important','High Priority','Urgent']].map(v=>`<option ${taskFilterState.priority===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Category<select onchange="setTaskFilter('category',this.value)">${['All',...['Home','Dance','School','Bills','Shopping','Appointments','Work','Other']].map(v=>`<option ${taskFilterState.category===v?'selected':''}>${v}</option>`).join('')}</select></label></div>`}
function setTaskFilter(key,value){taskFilterState[key]=value;render('tasks')}
function tasks(){const filtered=S.tasks.filter(t=>visible(t)&&(adult(S.viewer)?(taskFilterState.status==='All'||taskFilterState.status==='Open'&&t.status==='open'||taskFilterState.status==='Completed'&&t.status==='done'||taskFilterState.status==='Not Completed'&&t.status==='missed')&& (taskFilterState.assignee==='All'||t.who===taskFilterState.assignee)&&(taskFilterState.priority==='All'||t.priority===taskFilterState.priority)&&(taskFilterState.category==='All'||t.category===taskFilterState.category):t.status==='open'));return `${renderTopBar()}<div class=section><h2>${S.viewer==='Daughter'?'✅ My Stuff':'✅ Tasks & Chores'}</h2>${adult(S.viewer)?'<button class="btn primary" onclick="openAdd()">+ Add Task</button>':''}</div>${taskFilters()}${taskList(filtered)}`}
function detailRow(label,value){return `<div class=detail-row><dt>${label}</dt><dd>${value||'Not set'}</dd></div>`}
function openTaskDetails(id){const t=taskById(id);if(!t)return;const acknowledgements=(t.acknowledgements||[]).map(a=>`${displayName(a.person)} · ${timeLabel(a.acknowledgedAt)}`).join('<br>')||((t.acked||[]).map(displayName).join(', ')||'No acknowledgements yet');const completions=(t.completionHistory||[]).map(c=>`${displayName(c.completedBy)} · ${timeLabel(c.completedAt)}`).join('<br>');modal(`<h2>${t.title}</h2><p class="status-label ${taskStatus(t).toLowerCase().replaceAll(' ','-')}">${taskStatus(t)}</p><dl class=task-details data-task-id=${t.id}>${detailRow('Description / notes',t.description)}${detailRow('Assigned person',displayAssignee(t.who))}${detailRow('Created by',displayName(t.creator))}${detailRow('Priority',t.priority)}${detailRow('Visibility',visibilityName(t.visibility))}${detailRow('Category',t.category)}${detailRow('Due date',t.dueDate)}${detailRow('Due time',t.dueTime)}${detailRow('Repeat',t.repeat)}${detailRow('Acknowledgement required',t.ack?'Yes':'No')}${detailRow('Acknowledged by',acknowledgements)}${detailRow('Completion status',taskStatus(t))}${detailRow('Completed by',t.completedBy?displayName(t.completedBy):'')}${detailRow('Completed at',t.completedAt?timeLabel(t.completedAt):'')}${detailRow('Completion history',completions)}${detailRow('Not-completed reason',t.reason)}${detailRow('Reason recorded by',t.reasonBy?displayName(t.reasonBy):'')}${detailRow('Reason timestamp',t.reasonAt?timeLabel(t.reasonAt):'')}${detailRow('Created',timeLabel(t.createdAt))}${detailRow('Last updated',`${t.updatedBy?displayName(t.updatedBy)+' · ':''}${timeLabel(t.updatedAt)}`)}</dl>${canManageTask(t)?`<div class=actions><button class=btn onclick="openEditTask(${t.id})">Edit / Reassign</button>${t.status==='open'?`<button class="btn good" ${canCompleteTask(t)?'':'disabled'} onclick="manageComplete(${t.id})">Mark Complete</button><button class="btn bad" onclick="openMissReason(${t.id},true)">Mark Not Complete</button>`:`<button class=btn onclick="reopenTask(${t.id})">Reopen</button>`}<button class="btn bad" onclick="confirmDeleteTask(${t.id})">Delete</button></div>`:''}${!canManageTask(t)&&t.status==='open'&&(t.who===S.viewer||t.who==='Everyone')?`<div class=actions>${t.ack&&!(t.acked||[]).includes(S.viewer)?`<button class="btn primary" onclick="ack(${t.id})">Acknowledge</button>`:''}<button class="btn good" ${canCompleteTask(t)?'':'disabled'} onclick="done(${t.id})">Complete</button><button class="btn bad" onclick="openMissReason(${t.id},false)">Not Complete</button></div>`:''}`)}
const renderTaskDetails=openTaskDetails;
openTaskDetails=function(id){renderTaskDetails(id);const task=taskById(id);if(task?.recurrenceActive&&canManageTask(task))document.querySelector('#modal .actions')?.insertAdjacentHTML('beforeend',`<button class="btn" onclick="confirmStopTaskRecurrence(${id})">Stop future repeats</button>`)};
function confirmStopTaskRecurrence(id){const task=taskById(id);if(!task||!canManageTask(task))return;modal(`<h2>Stop recurring task?</h2><p>Keep existing occurrences and stop creating future copies of “${task.title}”?</p><div class=actions><button class=btn onclick="openTaskDetails(${id})">Cancel</button><button class="btn bad" onclick="mutate({action:'stop_recurrence',id:${id}},'tasks')">Stop recurrence</button></div>`)}
function confirmDeleteTask(id){const t=taskById(id);if(!t||!canManageTask(t))return;document.getElementById('modal')?.remove();modal(`<h2>Delete task?</h2><p>Delete “${t.title}”?</p><div class=actions><button class=btn onclick="openTaskDetails(${id})">Cancel</button><button class="btn bad" onclick="mutate({action:'delete',id:${id}},'tasks')">Delete Task</button></div>`)}
function manageComplete(id){return mutate({action:'done',id,manager:true})}
function reopenTask(id){return mutate({action:'reopen',id},'tasks')}
function openMissReason(id,manager){modal(`<h2>Mark Not Completed</h2><div class=field><label for=missReason>Reason</label><select id=missReason><option>Ran out of time</option><option>Waiting on someone/something</option><option>Rescheduled</option><option>No longer needed</option><option>Other</option></select></div><div class=field><label for=missExplanation>Additional explanation (optional)</label><textarea id=missExplanation rows=3 maxlength=1000></textarea></div><div class=actions><button class=btn onclick="openTaskDetails(${id})">Cancel</button><button class="btn bad" onclick="submitNotComplete(${id},${manager})">Save reason</button></div>`)}
function submitNotComplete(id,manager){const reasonCode=val('missReason'),explanation=val('missExplanation');return mutate({action:'miss',id,reasonCode,explanation,...manager?{manager:true}:{}},'tasks')}
function board(){const posts=[...S.posts].sort((a,b)=>Number(!!b.pinned)-Number(!!a.pinned)||String(b.createdAt||'').localeCompare(String(a.createdAt||'')));return `${renderTopBar()}<div class=section><h2>📣 Family Bulletin Board</h2><button class=btn onclick=openPost()>+ Post</button></div>${posts.map(p=>`<article class="card boardpost ${p.pinned?'pinned-post':''}"><div class=boardpost-head><b>${p.by==='Dad'?'👨':p.by==='Mom'?'👩':'👧'} ${displayName(p.by)}</b>${p.pinned?'<span class=board-label>📌 Pinned</span>':''}${p.important?'<span class=board-label>⭐ Important</span>':''}${adult(S.viewer)?`<button class=btn onclick="mutate({action:'pin',id:${p.id},pinned:${!p.pinned}},'board')">${p.pinned?'Unpin':'Pin'}</button>`:''}</div><p>${p.text}</p>${p.createdAt?`<time class=meta>${timeLabel(p.createdAt)}</time>`:''}<div class=reactions>${['❤️','👍','😂','🎉'].map(e=>`<button class=reaction aria-label="React ${e}; ${p.reacts?.[e]||0} reactions" onclick="react(${p.id},'${e}')">${e} ${p.reacts?.[e]||0}</button>`).join('')}</div>${p.ackRequired?`<div class=board-ack>${(p.acknowledgedBy||[]).includes(S.viewer)?'✅ You acknowledged this announcement.':`<button class="btn primary" onclick="mutate({action:'ack',id:${p.id}},'board')">Acknowledge</button>`}${adult(S.viewer)?`<span class=meta>${(p.acknowledgedBy||[]).length} of 3 acknowledged${p.acknowledgedBy?.length?` · ${(p.acknowledgedBy||[]).map(displayName).join(', ')}`:''}</span>`:''}</div>`:''}<div class=board-comments>${(p.comments||[]).map(comment=>`<div class=board-comment><div><b>${displayName(comment.by)}</b><p>${comment.text}</p><time class=meta>${timeLabel(comment.createdAt)}</time></div>${comment.by===S.viewer||adult(S.viewer)?`<button class=btn aria-label="Delete comment" onclick="deleteBoardComment(${p.id},${comment.id})">×</button>`:''}</div>`).join('')}<div class=board-comment-form><label class=sr-only for="boardComment${p.id}">Write a comment</label><textarea id="boardComment${p.id}" rows=2 maxlength=2000 placeholder="Write a comment"></textarea><button class=btn onclick="addBoardComment(${p.id})">Comment</button></div></div></article>`).join('')||'<div class=card>No family posts yet.</div>'}`}
function requestHistory(r){const responses=r.responses||[];if(!responses.length&&r.reply)return `<div class=request-history><p><b>${displayName(r.replyBy||r.creator)}</b>: ${displayReply(r)}</p></div>`;return responses.length?`<div class=request-history>${responses.map(response=>`<div class=request-message><b>${displayName(response.by)}${response.status&&response.status!=='Message'?` · ${response.status}`:''}</b><p>${response.reply}</p><time>${timeLabel(response.createdAt)}</time></div>`).join('')}</div>`:''}
function requestMeta(r){return `${r.date?`<p class=meta>Date: ${prettyDate(r.date,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}${r.time?` · ${r.time}`:''}</p>`:''}${r.description?`<p>${r.description}</p>`:''}`}
function ask(){return `${renderTopBar()}<div class=hero><h1>🙋 Ask ${displayName('Dad')} & ${displayName('Mom')}</h1><div>Need permission, a ride, or have a question? Ask us here! 💬</div></div><button class="btn primary" onclick=openAsk()>+ New Request</button><div class=section><h2>My Requests</h2></div>${S.requests.map(r=>`<div class=card><b>${r.type}</b><h3>${r.title||r.text}</h3>${r.text!==(r.title||r.text)?`<p>${r.text}</p>`:''}${requestMeta(r)}<div class="status ${r.status.toLowerCase()}">${r.status==='Pending'?'🟡':r.status==='Approved'?'🟢':'🔴'} ${r.status}</div>${requestHistory(r)}<div class=actions><button class=btn onclick="requestAction(${r.id},'reply')">💬 Reply</button></div></div>`).join('')||'<div class=card>No requests yet.</div>'}`}
function requests(){return `${renderTopBar()}<div class=section><h2>🙋 Parent Requests Inbox</h2></div>${S.requests.map(r=>`<div class=card><b>${displayName(r.creator)} · ${r.type}</b><h3>${r.title||r.text}</h3>${r.text!==(r.title||r.text)?`<p>${r.text}</p>`:''}${requestMeta(r)}<div class="status ${r.status.toLowerCase()}">${r.status}</div>${requestHistory(r)}<div class=actions>${r.status==='Pending'?`<button class="btn good" onclick="requestAction(${r.id},'Approved')">✅ Approve</button><button class="btn bad" onclick="requestAction(${r.id},'Denied')">❌ Deny</button>`:''}<button class=btn onclick="requestAction(${r.id},'reply')">💬 Ask a Question / Reply</button></div></div>`).join('')||'<div class=card>No family requests right now.</div>'}`}
function dance(){return `${renderTopBar()}<div class=hero><h1>💃 Dance Hub</h1><div>Everything dance, all in one place ✨</div></div><div class=grid>${[['🏠','Dance Home'],['📅','Schedule'],['🩰','Routines'],['🏆','Competitions'],['👗','Costumes'],['✅','Checklists']].map(x=>`<div class="card tile"><span class=emoji>${x[0]}</span><b>${x[1]}</b>${x[1]==='Competitions'?'<div class=meta>Saturday • Schedule Pending ⏳</div>':''}</div>`).join('')}</div>`}
function calendar(){return `${renderTopBar()}<div class=section><h2>📅 Family Calendar</h2></div>${S.events.map(e=>`<div class=card style="margin-bottom:10px"><b>${e.date}</b><p>${e.text}</p></div>`).join('')}`}
function tomorrow(){return `${renderTopBar()}<div class=hero><h1>🌙 Ready for Tomorrow?</h1><div>Pack it, plan it, then relax ✨</div></div>${taskList(S.tasks.filter(t=>visible(t)&&t.status==='open').slice(0,3))}<div class=card><b>📅 Tomorrow</b><p>💃 Dance practice • 5:30 PM</p><p>🎒 School day</p></div>`}
function recap(){const since=new Date(Date.now()-7*86400000).toISOString();const completed=S.tasks.filter(t=>t.status==='done'&&t.completedAt>=since).length;return `${renderTopBar()}<div class=hero><h1>📊 Our Week 🎉</h1><div>Nice teamwork, Martin-Riley family!</div></div><div class=grid><div class=card><div class=emoji>🔥</div><b>${S.streak} day streak</b></div><div class=card><div class=emoji>✅</div><b>${completed} completed in 7 days</b></div><div class=card><div class=emoji>🙋</div><b>${S.requests.filter(r=>r.status==='Approved').length} approved requests total</b></div><div class=card><div class=emoji>🎉</div><b>${S.posts.filter(p=>p.createdAt>=since).length} posts in 7 days</b></div></div>`}
function family(){return `${renderTopBar()}<div class=section><h2>👨‍👩‍👧 Family</h2></div>${['Dad','Mom','Daughter'].map(n=>`<div class="card task"><div class=avatar>${n==='Dad'?'👨':n==='Mom'?'👩':'👧'}</div><div><b>${displayName(n)}</b><div class=meta>${S.profiles?.[n]?.role||'Family Member'}${n==='Daughter'?' • 🔥 '+S.streak+' day streak':''}</div></div></div>`).join('')}<div class=section><h2>${S.viewer==='Daughter'?'Family Activity':'Recent Activity'}</h2></div>${activityList(S.activity.slice(0,8))}`}
function privacy(){return `${renderTopBar()}<div class=section><h2>🔐 Access & Privacy</h2></div><div class=card><b>🤖 ChatGPT default access</b><p>Tasks: Limited read-only</p><p>Family Calendar: Limited read-only</p><p>🔒 Me Only: Blocked</p><p>🔒 Adult Vault: Blocked</p><p>📍 Location: Blocked</p><p>💵 Financial information: Blocked</p></div><div class=card style="margin-top:12px"><b>Visibility rules</b><p>👨‍👩‍👧 Family • 🔒 Adults Only • 👤 Assigned Person • 🔐 Me Only</p></div>`}
function adultHomeAgenda(){const today=hubToday(),todayEvents=S.events.filter(event=>event.date===today),due=S.tasks.filter(task=>task.status==='open'&&task.dueDate===today),overdue=S.tasks.filter(taskOverdue),awaiting=S.tasks.filter(task=>task.status==='open'&&task.ack&&taskAwaitingAcknowledgement(task)),next=S.events.filter(event=>event.date>=today).sort((a,b)=>`${a.date}${a.startTime}`.localeCompare(`${b.date}${b.startTime}`))[0];return `<div class=dashboard-agenda><section><h3>Today’s events</h3>${todayEvents.map(event=>calendarEntry({kind:'event',item:event})).join('')||'<p class=meta>No events today.</p>'}</section><section><h3>Upcoming event</h3>${next?calendarEntry({kind:'event',item:next}):'<p class=meta>No upcoming events.</p>'}</section><section><h3>Tasks due today</h3>${due.length?taskList(due):'<p class=meta>No tasks due today.</p>'}</section><section><h3>Overdue</h3>${overdue.length?taskList(overdue):'<p class=meta>No overdue tasks.</p>'}</section><section><h3>Awaiting acknowledgement</h3>${awaiting.length?taskList(awaiting):'<p class=meta>No tasks awaiting acknowledgement.</p>'}</section></div>`}
function render(p='home'){if(!S.viewer){loginScreen();return}page=p;let fn={home,tasks,board,ask,requests,dance,calendar,tomorrow,recap,family,privacy,lists:()=>collection('lists'),vault:()=>collection('vault'),private:()=>collection('private'),reminders}[p]||home;let content=fn();if(p==='home'&&adult(S.viewer))content=content.replace('<div class=grid>',`${adultHomeAgenda()}<div class=grid>`);document.querySelector('#app').innerHTML=`<main class=shell>${content}</main>${nav()}`;window.scrollTo(0,0);markViewedNotifications(p)}
function modal(html){document.getElementById('modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class=modal id=modal onclick="if(event.target===this)this.remove()"><div class=sheet role=dialog aria-modal=true><button class="btn close-sheet" aria-label="Close" onclick="document.getElementById('modal').remove();render(page)">×</button>${html}</div></div>`)}function openTaskForm(){modal(`<h2>+ Add Task</h2><div class=field><label for=nt>Task or chore name</label><input id=nt maxlength=4000 required></div><div class=field><label for=ndesc>Description / notes (optional)</label><textarea id=ndesc rows=3 maxlength=4000></textarea></div><div class=row><div class=field><label for=nw>Assign to</label><select id=nw><option value="">Unassigned</option><option value="Dad">${displayName('Dad')}</option><option value="Mom">${displayName('Mom')}</option><option value="Daughter">${displayName('Daughter')}</option><option value="Everyone">Everyone</option></select></div><div class=field><label for=np>Priority</label><select id=np onchange="if(this.value==='Urgent')document.querySelector('#na').checked=true"><option>Normal</option><option>Important</option><option>High Priority</option><option>Urgent</option></select></div></div><div class=row><div class=field><label for=nv>Visibility</label><select id=nv><option value="Family">Family / Everyone</option><option value="Adults">Adults Only</option><option value="Assigned">Assigned Person</option><option value="Me">Me Only</option></select></div><div class=field><label for=nc>Category</label><select id=nc><option>Home</option><option>Dance</option><option>School</option><option>Bills</option><option>Shopping</option><option>Appointments</option><option>Work</option><option>Other</option></select></div></div><div class=row><div class=field><label for=nd>Due date</label><input id=nd type=date></div><div class=field><label for=ntime>Due time</label><input id=ntime type=time></div></div><div class=field><label for=nr>Repeat</label><select id=nr><option>One Time</option><option>Daily</option><option>Weekdays</option><option>Weekly</option><option>Monthly</option><option>Custom</option></select></div><label class=toggle><input type=checkbox id=na> Require acknowledgement</label><div class=actions><button class="btn primary" onclick=addTask()>+ Add Task</button></div>`)}
const escapeText=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeState(v){if(typeof v==='string')return escapeText(v);if(Array.isArray(v))return v.map(safeState);if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,x])=>[k,safeState(x)]));return v}
async function api(path,data){const res=await fetch('/api/'+path,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json','X-Hub-Request':'1'}:{},body:data?JSON.stringify(data):undefined,cache:'no-store'});const result=await res.json();if(!res.ok){if(res.status===401&&path!=='login'){S.viewer='';document.getElementById('recognition-celebration')?.remove();loginScreen()}throw Error(result.error||'Request failed')}return result}
async function loadProfiles(){try{const result=await api('profiles');S.profiles=safeState(result.profiles||{});if(!S.viewer)loginScreen()}catch{}}
let previous='', refreshing=false,refreshQueued=false,refreshWaiters=[];
async function refresh(force=false){if(refreshing){if(!force)return;refreshQueued=true;return new Promise(resolve=>refreshWaiters.push(resolve))}refreshing=true;try{const state=await api('state');const raw=JSON.stringify(state);S=safeState(state);if(force||raw!==previous){previous=raw;const modalEl=document.getElementById('modal'),taskDetails=modalEl?.querySelector('[data-task-id]'),eventDetails=modalEl?.querySelector('[data-event-id]');if(!modalEl)render(page);else if(taskDetails){const id=Number(taskDetails.dataset.taskId);modalEl.remove();if(taskById(id))openTaskDetails(id);else render(page)}else if(eventDetails){const id=Number(eventDetails.dataset.eventId);modalEl.remove();if(eventById(id))openEventDetails(id);else render(page)}}const el=document.getElementById('syncStatus');if(el)el.textContent='Synced just now'}catch(e){const el=document.getElementById('syncStatus');if(el)el.textContent='Connection lost · retrying';if(force&&S.viewer)alert(e.message)}finally{refreshing=false;if(refreshQueued){refreshQueued=false;const waiters=refreshWaiters;refreshWaiters=[];if(S.viewer)await refresh(true);for(const resolve of waiters)resolve()}}}
let writing=false;
function pendingButton(){const button=document.activeElement;if(button?.tagName!=='BUTTON')return ()=>{};const wasDisabled=button.disabled;button.disabled=true;button.setAttribute('aria-busy','true');return ()=>{if(button.isConnected){button.disabled=wasDisabled;button.removeAttribute('aria-busy')}}}
async function mutate(data,next=page){if(writing)return false;writing=true;const restoreButton=pendingButton();try{await api('action',data);document.getElementById('modal')?.remove();page=next;await refresh(true);return true}catch(e){alert(e.message);return false}finally{writing=false;restoreButton()}}
const val=id=>document.getElementById(id).value.trim();
async function addTask(){const who=val('nw'),visibility=val('nv');if(visibility==='Assigned'&&!['Dad','Mom','Daughter'].includes(who)){alert('Choose a person for Assigned Person visibility.');return}const record={title:val('nt'),description:val('ndesc'),who,priority:val('np'),visibility,ack:document.getElementById('na').checked,dueDate:val('nd'),dueTime:val('ntime'),category:val('nc'),repeat:val('nr'),customIntervalDays:Number(val('nInterval')||1)};const result=await mutate(editingTaskId?{action:'edit',id:editingTaskId,record}:{action:'create',kind:'tasks',record},'tasks');if(result)editingTaskId=null;return result}
function openEditTask(id){const t=taskById(id);if(!t||!canManageTask(t))return;editingTaskId=id;openTaskForm();for(const [field,value] of Object.entries({nt:t.title,ndesc:t.description||'',nw:t.who||'',np:t.priority,nv:t.visibility,nc:t.category||'Other',nd:t.dueDate||'',ntime:t.dueTime||'',nr:t.repeat||'One Time'})){document.getElementById(field).value=value}const acknowledgement=document.getElementById('na');acknowledgement.checked=!!t.ack;acknowledgement.disabled=t.priority==='Urgent';document.querySelector('#modal h2').textContent='Edit Task';document.querySelector('#modal .actions .primary').textContent='Save Changes'}
function ack(id){return mutate({action:'ack',id})}
const defaultModal=modal;
modal=function(html){if(html.includes('select id=nr'))html=html.replace('<select id=nr>','<select id=nr onchange="toggleCustomInterval()">').replace('</select></div><label class=toggle><input type=checkbox id=na>','</select></div><div class="field hide" id=customIntervalField><label for=nInterval>Repeat every (days)</label><input id=nInterval type=number min=1 max=366 value=1></div><label class=toggle><input type=checkbox id=na>');defaultModal(html)};
function toggleCustomInterval(){document.getElementById('customIntervalField')?.classList.toggle('hide',document.getElementById('nr')?.value!=='Custom')}
const originalOpenEditTask=openEditTask;
openEditTask=function(id){originalOpenEditTask(id);const interval=document.getElementById('nInterval'),task=taskById(id);if(interval&&task)interval.value=task.customIntervalDays||1;toggleCustomInterval()};
async function done(id){if(await mutate({action:'done',id})){const t=taskById(id);if(S.viewer==='Daughter'&&t?.category==='Home')celebrate()}}
function celebrate(){const d=document.createElement('div');d.className='celebrate';d.textContent='Done! ✅ Nice job! 🎉🌟';document.body.appendChild(d);setTimeout(()=>d.remove(),2200)}
function openPost(){modal(`<h2>📣 Share a family moment</h2><div class=field><label for=pt>Your update</label><textarea id=pt rows=4 maxlength=4000 required></textarea></div>${adult(S.viewer)?'<label class="toggle"><input id=postImportant type=checkbox onchange="document.getElementById(\'postAckRequired\').disabled=!this.checked"> Important announcement</label><label class="toggle"><input id=postAckRequired type=checkbox disabled> Ask family members to acknowledge</label>':''}<button class="btn primary" onclick=addPost()>Post</button>`)}
function addPost(){const record={text:val('pt')};if(adult(S.viewer)){record.important=!!document.getElementById('postImportant')?.checked;record.ackRequired=!!document.getElementById('postAckRequired')?.checked}return mutate({action:'create',kind:'posts',record},'board')}
function react(id,emoji){return mutate({action:'react',id,emoji})}
function addBoardComment(id){const comment=document.getElementById(`boardComment${id}`)?.value.trim();return mutate({action:'comment',id,comment},'board')}
function deleteBoardComment(id,commentId){if(confirm('Remove this comment?'))return mutate({action:'delete_comment',id,commentId},'board')}
function openAsk(){modal(`<h2>🙋 Ask ${displayName('Dad')} & ${displayName('Mom')}</h2><div class=field><label for=rt>Type</label><select id=rt>${['Permission','Purchase','Ride','Sleepover/Friend','Schedule Change','Chore/Task','Question','Other'].map(type=>`<option>${type}</option>`).join('')}</select></div><div class=field><label for=rq>What would you like to ask?</label><textarea id=rq rows=3 maxlength=4000 required></textarea></div><div class=row><div class=field><label for=requestDate>Date (optional)</label><input id=requestDate type=date></div><div class=field><label for=requestTime>Time (optional)</label><input id=requestTime type=time></div></div><div class=field><label for=requestDetails>Additional details / explanation (optional)</label><textarea id=requestDetails rows=3 maxlength=4000></textarea></div><button class="btn primary" onclick=addRequest()>Send request 💬</button>`)}
function addRequest(){return mutate({action:'create',kind:'requests',record:{title:val('rq'),text:val('rq'),type:val('rt'),date:val('requestDate'),time:val('requestTime'),description:val('requestDetails')}},'ask')}
function requestAction(id,action){const replyMode=action==='reply',request=S.requests.find(item=>item.id===Number(id));if(!request)return;const title=replyMode?'Ask a Question / Reply':action==='Approved'?'Approve Request':'Deny Request',label=replyMode?'Your message':action==='Approved'?'Optional note / conditions':'Optional reason',button=replyMode?'Send reply':action==='Approved'?'Approve request':'Deny request',calendarChoice=action==='Approved'&&request.date?'<label class="toggle request-calendar-choice"><input id=requestAddCalendar type=checkbox> Add to Family Calendar</label>':'';modal(`<h2>${title}</h2><p>${request.title||request.text}</p><div class=field><label for=requestResponse>${label}</label><textarea id=requestResponse rows=3 maxlength=1000 ${replyMode?'required':''}></textarea></div>${calendarChoice}<div class=actions><button class=btn onclick="render(page)">Cancel</button><button class="btn ${action==='Denied'?'bad':'primary'}" onclick="submitRequestAction(${id},'${action}')">${button}</button></div>`)}
function submitRequestAction(id,action){const reply=val('requestResponse');if(action==='reply')return mutate({action:'reply',id,reply},'requests');const data={action:'decision',id,status:action,reply};if(action==='Approved')data.addToCalendar=!!document.getElementById('requestAddCalendar')?.checked;return mutate(data,'requests')}
function loginScreen(){document.querySelector('#app').innerHTML=`<main class="shell login"><div class=hero><div class=emoji>🏡</div><h1>Martin-Riley<br>Family Hub</h1><p>A little less juggling.<br>A lot more together.</p></div><form class=card onsubmit="event.preventDefault();signIn()"><h2>Welcome home 💜</h2><div class=field><label for=loginName>Who is signing in?</label><select id=loginName>${['Dad','Mom','Daughter'].map(id=>`<option value="${id}">${displayName(id)}</option>`).join('')}</select></div><div class=field><label for=loginPassword>Your password</label><input id=loginPassword type=password autocomplete=current-password required></div><p id=loginError role=alert></p><button class="btn primary" id=loginButton>Come on in →</button><p class=meta>Private to our family. Each person has their own account.</p></form></main>`}
async function signIn(){const b=document.getElementById('loginButton');b.disabled=true;try{await api('login',{name:val('loginName'),password:document.getElementById('loginPassword').value});page='home';await refresh(true)}catch(e){document.getElementById('loginError').textContent=e.message;b.disabled=false}}
async function logout(){try{await api('logout',{});S={viewer:'',profiles:S.profiles};previous='';document.getElementById('modal')?.remove();document.getElementById('recognition-celebration')?.remove();loginScreen()}catch(e){alert(e.message)}}
function collection(which){const title={lists:'🛒 Shared Lists',vault:'🔒 Adult Vault',private:'💌 Me Only'}[which];if(which==='vault'&&!adult(S.viewer))return home();const items=which==='lists'?S.lists:S.notes.filter(n=>n.visibility===(which==='vault'?'Adults':'Me'));return `${renderTopBar()}<div class=hero><h1>${title}</h1><p>${which==='lists'?'Groceries, packing, and the little things.':which==='vault'?`A private space for ${displayName('Dad')} and ${displayName('Mom')}.`:'Just for you. Your family cannot see these items.'}</p></div><button class="btn primary" onclick="openItem('${which}')">+ Add item</button><div class=section></div>${items.map(n=>`<div class="card task"><div class=grow><b>${n.title||n.text}</b><p class=meta>${n.checked?'✅ Checked off':'○ Open'} · ${displayName(n.creator)}</p></div>${which==='lists'?`<button class=btn onclick="mutate({action:'check',id:${n.id}})">${n.checked?'Undo':'Check'}</button>`:''}${n.creator===S.viewer||adult(S.viewer)&&n.visibility!=='Me'?`<button class=btn aria-label="Delete item" onclick="if(confirm('Delete this item?'))mutate({action:'delete',id:${n.id}})">×</button>`:''}</div>`).join('')||'<div class=card>No items yet. Make this space yours ✨</div>'}`}
function openItem(which){if(which==='events'){openEventForm();return}const label={dance:'dance item',lists:'list item',private:'note',vault:'vault note'}[which]||'item';modal(`<h2>Add ${label}</h2><div class=field><label for=itemText>Details</label><textarea id=itemText maxlength=4000 required></textarea></div>${which==='dance'?'<div class=field><label for=itemCategory>Section</label><select id=itemCategory><option>Competitions</option><option>Schedule</option><option>Routines</option><option>Costumes</option><option>Checklists</option></select></div><div class=field><label for=itemDate>Date (optional)</label><input id=itemDate type=date></div>':''}<button class="btn primary" onclick="createItem('${which}')">Save</button>`)}
function createItem(which){const record={text:val('itemText'),visibility:which==='vault'?'Adults':which==='private'?'Me':'Family'};if(which==='dance'){record.category=val('itemCategory');record.date=val('itemDate')}return mutate({action:'create',kind:which==='vault'||which==='private'?'notes':which,record},which)}
const taskFormBeforeMaddox=openTaskForm;
function managedFamilyMembers(){return Object.values(S.familyMembers||{}).filter(member=>member.profileType==='managed_child'&&!member.hasAccount)}
function isManagedMember(memberId){return !!S.familyMembers?.[memberId]&&S.familyMembers[memberId].profileType==='managed_child'&&!S.familyMembers[memberId].hasAccount}
const taskListBeforeManagedMember=taskList;
taskList=function(tasks){let html=taskListBeforeManagedMember(tasks);if(!adult(S.viewer))return html;for(const task of tasks){if(!isManagedMember(task.who)||task.status!=='open')continue;const pattern=new RegExp(`(<div class="card task task-card [^"]+" role=button tabindex=0 onclick="openTaskDetails\\(${task.id}\\)"[\\s\\S]*?<div class=actions>)([\\s\\S]*?)(<\\/div><\\/div><\\/div>)`);html=html.replace(pattern,(_match,open,actions,close)=>`${open}${actions}<button class="btn good" onclick="event.stopPropagation();manageComplete(${task.id})">Mark managed item complete</button><button class="btn bad" onclick="event.stopPropagation();openMissReason(${task.id},true)">Not complete</button>${close}`)}return html};
function updateManagedTaskAck(){const managed=isManagedMember(document.getElementById('nw')?.value),ack=document.getElementById('na');if(ack){ack.disabled=managed;if(managed)ack.checked=false;const label=ack.parentElement;if(label)label.lastChild.textContent=managed?' Acknowledgement unavailable · no child login':' Require acknowledgement'}}
openTaskForm=function(){taskFormBeforeMaddox();if(adult(S.viewer)){const select=document.getElementById('nw'),members=managedFamilyMembers();if(select&&members.length)select.insertAdjacentHTML('beforeend',members.map(member=>`<option value="${member.memberId}">${member.displayName} · parent-managed</option>`).join(''));if(select)select.addEventListener('change',updateManagedTaskAck);updateManagedTaskAck()}};
const taskFiltersBeforeMaddox=taskFilters;
taskFilters=function(){const options=managedFamilyMembers().map(member=>`<option value="${member.memberId}">${member.displayName} · managed profile</option>`).join('');return taskFiltersBeforeMaddox().replace(/(<option value="Everyone"[^>]*>Everyone<\/option>)/,`${options}$1`)};
const openEditTaskBeforeMaddox=openEditTask;
openEditTask=function(id){openEditTaskBeforeMaddox(id);updateManagedTaskAck()};
function openManagedActivityForm(id=null){if(!adult(S.viewer))return;const activity=id?(S.activities||[]).find(item=>item.id===Number(id)):null;if(id&&!activity)return;modal(`<h2>${activity?'Edit':'Add'} Maddox activity</h2><div class=field><label for=maddoxSport>Sport / activity</label><input id=maddoxSport maxlength=300 value="${activity?.activityType||''}" required></div><div class=field><label for=maddoxEventType>Schedule item</label><select id=maddoxEventType>${['Practice','Game / Event','School Activity','Camp','Other'].map(value=>`<option ${activity?.eventType===value?'selected':''}>${value}</option>`).join('')}</select></div><div class=field><label for=maddoxOrganization>Team / organization</label><input id=maddoxOrganization maxlength=2000 value="${activity?.organization||''}"></div><div class=field><label for=maddoxSeason>Season</label><input id=maddoxSeason maxlength=2000 value="${activity?.season||''}"></div><div class=row><div class=field><label for=maddoxDate>Date</label><input id=maddoxDate type=date value="${activity?.date||''}" required></div><div class=field><label for=maddoxStart>Start time</label><input id=maddoxStart type=time value="${activity?.startTime||''}"></div><div class=field><label for=maddoxEnd>End time</label><input id=maddoxEnd type=time value="${activity?.endTime||''}"></div></div><div class=field><label for=maddoxLocation>Location</label><input id=maddoxLocation maxlength=2000 value="${activity?.location||''}"></div>${danceTextarea('maddoxEquipment','Equipment / packing notes',activity?.equipmentNotes)}${danceTextarea('maddoxParentNotes','Parent notes',activity?.parentNotes)}<label class="toggle"><input id=maddoxReminder type=checkbox ${activity?.reminderOffsets?.length?'checked':''}> Remind family on the activity date</label><div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('family')">Cancel</button><button class="btn primary" onclick="saveManagedActivity(${activity?.id||'null'})">${activity?'Save changes':'Save activity'}</button></div>`)}
function saveManagedActivity(id){const sport=val('maddoxSport'),eventType=val('maddoxEventType'),record={memberId:'Maddox',activityName:`${sport} ${eventType}`,activityType:sport,eventType,organization:val('maddoxOrganization'),season:val('maddoxSeason'),date:val('maddoxDate'),startTime:val('maddoxStart'),endTime:val('maddoxEnd'),location:val('maddoxLocation'),equipmentNotes:val('maddoxEquipment'),parentNotes:val('maddoxParentNotes'),reminderOffsets:document.getElementById('maddoxReminder').checked?[0]:[]};return mutate(id?{action:'edit',id,record}:{action:'create',kind:'activities',record},'family')}
function deleteManagedActivity(id){const activity=(S.activities||[]).find(item=>item.id===Number(id));if(!adult(S.viewer)||!activity)return;modal(`<h2>Remove ${activity.activityName}?</h2><p>This removes the activity and its generated Family Calendar entry.</p><div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('family')">Cancel</button><button class="btn bad" onclick="mutate({action:'delete',id:${id}},'family')">Delete activity</button></div>`)}
const familyBeforeMaddox=family;
family=function(){const html=familyBeforeMaddox(),member=S.familyMembers?.Maddox;if(!member)return html;const activities=(S.activities||[]).filter(item=>item.memberId==='Maddox').sort((a,b)=>`${a.date}${a.startTime||''}`.localeCompare(`${b.date}${b.startTime||''}`));return `${html}<section class=maddox-profile><div class=maddox-profile-heading><div><span class=maddox-avatar>${member.avatar||'🧒'}</span><div><h2>${member.displayName}</h2><p>${member.role} · No login or device · Managed by Jermaine and Stephanie</p></div></div>${adult(S.viewer)?'<button class="btn primary" onclick="openManagedActivityForm()">+ Activity</button>':''}</div><p class=meta>Activities &amp; Sports</p>${activities.map(item=>`<article class=maddox-activity><div><b>${item.activityName}</b><span class=meta>${item.organization||'Activity'}${item.season?' · '+item.season:''} · ${danceDate(item.date)}${item.startTime?' · '+item.startTime:''}${item.endTime?'–'+item.endTime:''}</span>${item.location?`<span class=meta>${item.location}</span>`:''}${item.equipmentNotes?`<p>${item.equipmentNotes}</p>`:''}${item.parentNotes?`<p>${item.parentNotes}</p>`:''}</div>${adult(S.viewer)?`<div class=actions><button class=btn onclick="openManagedActivityForm(${item.id})">Edit</button><button class="btn bad" onclick="deleteManagedActivity(${item.id})">Delete</button></div>`:''}</article>`).join('')||'<p class=meta>No activities scheduled yet.</p>'}</section>`};
const calendarEntryBeforeMaddox=calendarEntry;
calendarEntry=function(entry){const markup=calendarEntryBeforeMaddox(entry);return entry.kind==='event'&&entry.item.description?markup.replace('</button>',`<span>${entry.item.description}</span></button>`):markup};
function managedActivityField(memberId,key,label,value='',type='text'){const id=`managed-${memberId}-${key}`;return `<div class=field><label for="${id}">${label}</label><input id="${id}" type=${type} maxlength=2000 value="${value||''}"></div>`}
function managedActivityArea(memberId,key,label,value=''){const id=`managed-${memberId}-${key}`;return `<div class=field><label for="${id}">${label}</label><textarea id="${id}" rows=3 maxlength=2000>${value||''}</textarea></div>`}
function managedActivitySelect(memberId,key,label,options,selected){const id=`managed-${memberId}-${key}`;return `<div class=field><label for="${id}">${label}</label><select id="${id}">${options.map(value=>`<option ${selected===value?'selected':''}>${value}</option>`).join('')}</select></div>`}
function openManagedProfileActivity(memberId,activityId=null){if(!adult(S.viewer)||!isManagedMember(memberId))return;const activity=activityId?(S.activities||[]).find(item=>item.id===Number(activityId)&&item.memberId===memberId):null;if(activityId&&!activity)return;const types=['Practice','Game / Event','School Activity','Camp','Other'];modal(`<h2>${activity?'Edit':'Add'} ${displayName(memberId)} activity</h2>${managedActivityField(memberId,'sport','Sport / activity',activity?.activityType||'','text')}${managedActivitySelect(memberId,'type','Schedule item',types,activity?.eventType||'Practice')}${managedActivityField(memberId,'organization','Team / organization',activity?.organization)}${managedActivityField(memberId,'season','Season',activity?.season)}${managedActivityField(memberId,'date','Date',activity?.date,'date')}<div class=row>${managedActivityField(memberId,'start','Start time',activity?.startTime,'time')}${managedActivityField(memberId,'end','End time',activity?.endTime,'time')}</div>${managedActivityField(memberId,'location','Location',activity?.location)}${managedActivityArea(memberId,'equipment','Equipment / packing notes',activity?.equipmentNotes)}${managedActivityArea(memberId,'notes','Parent notes',activity?.parentNotes)}<label class="toggle"><input id="managed-${memberId}-reminder" type=checkbox ${activity?.reminderOffsets?.length?'checked':''}> Remind family on the activity date</label><div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('family')">Cancel</button><button class="btn primary" onclick="saveManagedProfileActivity('${memberId}',${activity?.id||'null'})">${activity?'Save changes':'Save activity'}</button></div>`)}
function saveManagedProfileActivity(memberId,activityId){const value=key=>document.getElementById(`managed-${memberId}-${key}`)?.value.trim()||'',record={memberId,activityName:`${value('sport')} ${value('type')}`,activityType:value('sport'),eventType:value('type'),organization:value('organization'),season:value('season'),date:value('date'),startTime:value('start'),endTime:value('end'),location:value('location'),equipmentNotes:value('equipment'),parentNotes:value('notes'),reminderOffsets:document.getElementById(`managed-${memberId}-reminder`)?.checked?[0]:[]};return mutate(activityId?{action:'edit',id:activityId,record}:{action:'create',kind:'activities',record},'family')}
function confirmDeleteManagedActivity(activityId){const activity=(S.activities||[]).find(item=>item.id===Number(activityId));if(!adult(S.viewer)||!activity||!isManagedMember(activity.memberId))return;modal(`<h2>Remove ${activity.activityName}?</h2><p>This removes the activity and its generated Family Calendar entry.</p><div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('family')">Cancel</button><button class="btn bad" onclick="mutate({action:'delete',id:${activity.id}},'family')">Delete activity</button></div>`)}
const openEventFormBeforeManagedMember=openEventForm;
openEventForm=function(eventId=null){openEventFormBeforeManagedMember(eventId);if(!adult(S.viewer))return;const fieldset=document.querySelector('#modal fieldset'),event=eventId?eventById(eventId):null;for(const member of managedFamilyMembers()){fieldset?.insertAdjacentHTML?.('beforeend',`<label class=check-option><input type=checkbox name=eventPeople value="${member.memberId}" ${event?.people?.includes(member.memberId)?'checked':''}> ${member.displayName} · managed profile</label>`)}};
const familyMembersBase=familyBeforeMaddox;
family=function(){const clean=familyMembersBase().replace(/<section class=maddox-profile>[\s\S]*?<\/section>/,'');const profiles=managedFamilyMembers();if(!profiles.length)return clean;const sections=profiles.map(member=>{const activities=(S.activities||[]).filter(item=>item.memberId===member.memberId).sort((a,b)=>`${a.date}${a.startTime||''}`.localeCompare(`${b.date}${b.startTime||''}`));return `<section class=maddox-profile><div class=maddox-profile-heading><div><span class=maddox-avatar>${member.avatar||'🧒'}</span><div><h2>${member.displayName}</h2><p>Managed Child Profile · No login or device · Managed by ${member.managedBy?.map(displayName).join(' and ')||'parents'}</p></div></div>${adult(S.viewer)?`<button class="btn primary" onclick="openManagedProfileActivity('${member.memberId}')">+ Activity</button>`:''}</div><p class=meta>Activities &amp; Sports</p>${activities.map(item=>`<article class=maddox-activity><div><b>${item.activityName}</b><span class=meta>${item.organization||'Activity'}${item.season?' · '+item.season:''} · ${danceDate(item.date)}${item.startTime?' · '+item.startTime:''}${item.endTime?'–'+item.endTime:''}</span>${item.location?`<span class=meta>${item.location}</span>`:''}${item.equipmentNotes?`<p>${item.equipmentNotes}</p>`:''}${item.parentNotes?`<p>${item.parentNotes}</p>`:''}</div>${adult(S.viewer)?`<div class=actions><button class=btn onclick="openManagedProfileActivity('${member.memberId}',${item.id})">Edit</button><button class="btn bad" onclick="confirmDeleteManagedActivity(${item.id})">Delete</button></div>`:''}</article>`).join('')||'<p class=meta>No activities scheduled yet.</p>'}</section>`}).join('');return clean+sections};
const calendarCategories=['Family','Appointment','School','Dance','Work','Bills','Travel','Other'];
function managedActivityDateLine(activity){const date=activity.date?prettyDate(activity.date,{weekday:'short',month:'short',day:'numeric'}):'',time=[activity.startTime,activity.endTime].filter(Boolean).join('–');return [date,time].filter(Boolean).join(' · ')}
family=function(){const base=familyMembersBase(),profiles=managedFamilyMembers();if(!profiles.length)return base;const sections=profiles.map(member=>{const activities=(S.activities||[]).filter(item=>item.memberId===member.memberId).sort((a,b)=>`${a.date}${a.startTime||''}`.localeCompare(`${b.date}${b.startTime||''}`));return `<section class=maddox-profile><div class=maddox-profile-heading><div><span class=maddox-avatar>${member.avatar||'🧒'}</span><div><h2>${member.displayName}</h2><p>Managed Child Profile · No login or device · Managed by ${member.managedBy?.map(displayName).join(' and ')||'parents'}</p></div></div>${adult(S.viewer)?`<button class="btn primary" onclick="openManagedProfileActivity('${member.memberId}')">+ Activity</button>`:''}</div><p class=meta>Activities &amp; Sports</p>${activities.map(item=>`<article class=maddox-activity><div class=maddox-activity-content><b class=maddox-activity-title>${item.activityName}</b><span class=maddox-activity-kind>🏃 ${item.activityType} · ${item.eventType}</span><span class=maddox-activity-date>📅 ${managedActivityDateLine(item)}</span>${item.organization||item.season?`<span class=meta>${[item.organization,item.season].filter(Boolean).join(' · ')}</span>`:''}${item.location?`<span class=maddox-activity-location>📍 ${item.location}</span>`:''}${item.equipmentNotes?`<p class=maddox-activity-equipment>🎒 ${item.equipmentNotes}</p>`:''}${adult(S.viewer)&&item.parentNotes?`<p class=maddox-parent-notes>Parent notes · ${item.parentNotes}</p>`:''}</div>${adult(S.viewer)?`<div class=actions><button class=btn onclick="openManagedProfileActivity('${member.memberId}',${item.id})">Edit</button><button class="btn bad" onclick="confirmDeleteManagedActivity(${item.id})">Delete</button></div>`:''}</article>`).join('')||'<p class=meta>No activities scheduled yet.</p>'}</section>`}).join('');return base+sections};
let calendarMode='month',calendarDate=new Date(),selectedCalendarDate='';let editingEventId=null;
function hubToday(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:S.timezone||'UTC',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return `${parts.find(p=>p.type==='year').value}-${parts.find(p=>p.type==='month').value}-${parts.find(p=>p.type==='day').value}`}
function dateFromKey(key){const [year,month,day]=key.split('-').map(Number);return new Date(year,month-1,day)}
function dateKey(date){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function prettyDate(key,options={weekday:'long',month:'long',day:'numeric'}){return dateFromKey(key).toLocaleDateString([],options)}
function calendarItemsForDate(key){return [...S.events.filter(e=>e.date===key).map(item=>({kind:'event',item})),...S.tasks.filter(t=>t.dueDate===key).map(item=>({kind:'task',item})),...S.dance.filter(d=>!d.archived&&(d.date||d.dueDate)===key).map(item=>({kind:'dance',item}))].sort((a,b)=>String(a.item.startTime||a.item.dueTime||'').localeCompare(String(b.item.startTime||b.item.dueTime||'')))}
function calendarItemLabel(entry){const item=entry.item;return entry.kind==='dance'?(item.title||item.text):item.title}
function calendarItemClick(entry){if(entry.kind==='task')return `openTaskDetails(${entry.item.id})`;if(entry.kind==='event')return `openEventDetails(${entry.item.id})`;return `openDanceDetails(${entry.item.id})`}
function calendarEntry(entry){const item=entry.item,kindLabel=entry.kind==='event'?'Calendar event':entry.kind==='task'?'Task due':'Dance item',time=item.startTime||item.dueTime||'';return `<button type=button class="calendar-entry ${entry.kind} ${entry.kind==='event'?`category-${String(item.category||'Family').toLowerCase().replaceAll(' ','-')}`:''}" onclick="${calendarItemClick(entry)}"><span class=calendar-entry-type>${entry.kind==='event'?'📅':entry.kind==='task'?'⏳':'💃'} ${kindLabel}</span><b>${calendarItemLabel(entry)}</b>${time?`<span>${time}</span>`:''}${entry.kind==='event'&&item.location?`<span>${item.location}</span>`:''}</button>`}
function canManageEvent(event){return adult(S.viewer)&&(event.creator===S.viewer||event.visibility!=='Me')}
function eventById(id){return S.events.find(event=>event.id===Number(id))}
function openEventForm(id=null){const event=id?eventById(id):null;if(id&&(!event||!canManageEvent(event)))return;editingEventId=event?.id||null;const date=event?.date||selectedCalendarDate||hubToday(),people=['Dad','Mom','Daughter'];modal(`<h2>${event?'Edit calendar event':'Add calendar event'}</h2><div class=field><label for=eventTitle>Title</label><input id=eventTitle maxlength=4000 required></div><div class=field><label for=eventDescription>Description / notes</label><textarea id=eventDescription rows=3 maxlength=4000></textarea></div><div class=row><div class=field><label for=eventDate>Date</label><input id=eventDate type=date required></div><label class="toggle event-all-day"><input id=eventAllDay type=checkbox onchange="document.querySelector('#eventTimes').classList.toggle('hide',this.checked)"> All day</label></div><div id=eventTimes class=row><div class=field><label for=eventStart>Start time</label><input id=eventStart type=time></div><div class=field><label for=eventEnd>End time</label><input id=eventEnd type=time></div></div><div class=row><div class=field><label for=eventCategory>Category</label><select id=eventCategory>${calendarCategories.map(category=>`<option>${category}</option>`).join('')}</select></div><div class=field><label for=eventVisibility>Visibility</label><select id=eventVisibility><option value="Family">Family / Everyone</option>${adult(S.viewer)?'<option value="Adults">Adults Only</option>':''}<option value="Assigned">Assigned Person</option><option value="Me">Me Only</option></select></div></div><div class=field><label for=eventWho>Assigned person (for Assigned visibility)</label><select id=eventWho><option value="Everyone">Everyone</option><option value="Dad">${displayName('Dad')}</option><option value="Mom">${displayName('Mom')}</option><option value="Daughter">${displayName('Daughter')}</option></select></div><fieldset class=field><legend>Relevant family members</legend>${people.map(person=>`<label class=check-option><input type=checkbox name=eventPeople value="${person}"> ${displayName(person)}</label>`).join('')}</fieldset><div class=field><label for=eventLocation>Location</label><input id=eventLocation maxlength=4000></div><div class=row><div class=field><label for=eventRepeat>Repeat</label><select id=eventRepeat>${['One Time','Daily','Weekdays','Weekly','Monthly','Custom'].map(repeat=>`<option>${repeat}</option>`).join('')}</select></div><div class=field><label for=eventInterval>Custom interval (days)</label><input id=eventInterval type=number min=1 max=366 value=1></div></div><fieldset class=field><legend>Remind me</legend>${[[1440,'1 day before'],[60,'1 hour before'],[0,'At start time']].map(([offset,label])=>`<label class=check-option><input type=checkbox name=eventReminder value="${offset}"> ${label}</label>`).join('')}</fieldset><div class=actions><button class="btn primary" onclick=saveCalendarEvent()>${event?'Save changes':'Create event'}</button></div>`);document.getElementById('eventTitle').value=event?.title||'';document.getElementById('eventDescription').value=event?.description||'';document.getElementById('eventDate').value=date;document.getElementById('eventAllDay').checked=event?.allDay??true;document.getElementById('eventTimes').classList.toggle('hide',document.getElementById('eventAllDay').checked);document.getElementById('eventStart').value=event?.startTime||'';document.getElementById('eventEnd').value=event?.endTime||'';document.getElementById('eventCategory').value=calendarCategories.includes(event?.category)?event.category:'Family';document.getElementById('eventVisibility').value=event?.visibility||'Family';document.getElementById('eventWho').value=event?.who||'Everyone';document.getElementById('eventLocation').value=event?.location||'';document.getElementById('eventRepeat').value=event?.repeat||'One Time';document.getElementById('eventInterval').value=event?.customIntervalDays||1;const selectedPeople=event?.people?.length?event.people:(event?.who&&event.who!=='Everyone'?[event.who]:[]);document.querySelectorAll('[name=eventPeople]').forEach(input=>input.checked=selectedPeople.includes(input.value));const offsets=event?.reminderOffsets||[1440,60,0];document.querySelectorAll('[name=eventReminder]').forEach(input=>input.checked=offsets.includes(Number(input.value)))}
async function saveCalendarEvent(){const visibility=val('eventVisibility'),who=val('eventWho');if(visibility==='Assigned'&&!['Dad','Mom','Daughter'].includes(who)){alert('Choose an assigned person.');return}const allDay=document.getElementById('eventAllDay').checked,record={title:val('eventTitle'),description:val('eventDescription'),date:val('eventDate'),startTime:allDay?'':val('eventStart'),endTime:allDay?'':val('eventEnd'),allDay,category:val('eventCategory'),who,people:[...document.querySelectorAll('[name=eventPeople]:checked')].map(input=>input.value),visibility,location:val('eventLocation'),repeat:val('eventRepeat'),customIntervalDays:Number(val('eventInterval')),reminderOffsets:[...document.querySelectorAll('[name=eventReminder]:checked')].map(input=>Number(input.value))};const id=editingEventId;const saved=await mutate(id?{action:'edit',id,record}:{action:'create',kind:'events',record},'calendar');if(saved)editingEventId=null;return saved}
function openEventDetails(id){const event=eventById(id);if(!event)return;const people=(event.people||[]).map(displayName).join(', ')||displayAssignee(event.who);modal(`<h2>${event.title}</h2><dl class=task-details>${detailRow('Description / notes',event.description)}${detailRow('Date',prettyDate(event.date))}${detailRow('Start time',event.allDay?'All day':event.startTime)}${detailRow('End time',event.allDay?'All day':event.endTime)}${detailRow('All-day status',event.allDay?'Yes':'No')}${detailRow('Category',event.category)}${detailRow('Relevant family member(s)',people)}${detailRow('Visibility',visibilityName(event.visibility))}${detailRow('Location',event.location)}${detailRow('Repeat',event.repeat)}${detailRow('Created by',displayName(event.creator))}${detailRow('Created',timeLabel(event.createdAt))}${detailRow('Last updated',`${event.updatedBy?displayName(event.updatedBy)+' · ':''}${timeLabel(event.updatedAt)}`)}</dl>${canManageEvent(event)?`<div class=actions><button class=btn onclick="openEventForm(${event.id})">Edit / Reschedule</button><button class="btn bad" onclick="confirmDeleteEvent(${event.id})">Delete</button></div>`:''}`)}
const renderEventDetails=openEventDetails;
openEventDetails=function(id){const event=eventById(id);if(event?.sourceDanceId&&danceById(event.sourceDanceId)){openDanceDetails(event.sourceDanceId);return}renderEventDetails(id);const details=document.querySelector('#modal .task-details');if(details)details.dataset.eventId=id;if(event?.recurrenceActive&&canManageEvent(event))document.querySelector('#modal .actions')?.insertAdjacentHTML('beforeend',`<button class="btn" onclick="confirmStopEventRecurrence(${id})">Stop future repeats</button>`)};
function confirmStopEventRecurrence(id){const event=eventById(id);if(!event||!canManageEvent(event))return;modal(`<h2>Stop recurring event?</h2><p>Keep existing events and stop creating future copies of “${event.title}”?</p><div class=actions><button class=btn onclick="openEventDetails(${id})">Cancel</button><button class="btn bad" onclick="mutate({action:'stop_recurrence',id:${id}},'calendar')">Stop recurrence</button></div>`)}
function confirmDeleteEvent(id){const event=eventById(id);if(!event||!canManageEvent(event))return;modal(`<h2>Delete calendar event?</h2><p>Delete “${event.title}”?</p><div class=actions><button class=btn onclick="openEventDetails(${id})">Cancel</button><button class="btn bad" onclick="mutate({action:'delete',id:${id}},'calendar')">Delete Event</button></div>`)}
function openDanceDetails(id){const item=S.dance.find(d=>d.id===Number(id));if(!item)return;modal(`<h2>${item.title||item.text}</h2><dl class=task-details>${detailRow('Type','Dance item')}${detailRow('Category',item.category)}${detailRow('Date',item.date?prettyDate(item.date):'')}${detailRow('Created by',displayName(item.creator))}</dl>`)}
function calendar(){const today=hubToday(),shown=dateKey(new Date(calendarDate.getFullYear(),calendarDate.getMonth(),1)),monthStart=dateFromKey(shown),offset=(monthStart.getDay()+6)%7,gridStart=new Date(monthStart);gridStart.setDate(gridStart.getDate()-offset);const selected=selectedCalendarDate||today;const allEntries=[...S.events.map(item=>({kind:'event',item})),...S.tasks.filter(task=>task.dueDate).map(item=>({kind:'task',item})),...S.dance.filter(item=>item.date||item.dueDate).map(item=>({kind:'dance',item}))];const dayCells=Array.from({length:42},(_,index)=>{const date=new Date(gridStart);date.setDate(gridStart.getDate()+index);const key=dateKey(date),entries=calendarItemsForDate(key);return `<button class="calendar-day ${date.getMonth()===monthStart.getMonth()?'':'outside'} ${key===selected?'selected':''} ${key===today?'today':''}" onclick="selectCalendarDay('${key}')"><span class=calendar-day-number>${date.getDate()}</span><span class=calendar-day-count>${entries.length?entries.length+' item'+(entries.length===1?'':'s'):''}</span><span class=calendar-dots>${[...new Set(entries.map(entry=>entry.kind==='event'?`event category-${String(entry.item.category||'Family').toLowerCase().replaceAll(' ','-')}`:entry.kind))].slice(0,3).map(kind=>`<i class="${kind}"></i>`).join('')}</span></button>`}).join('');const selectedItems=calendarItemsForDate(selected);const agenda=allEntries.filter(entry=>{const date=entry.kind==='event'?entry.item.date:entry.kind==='task'?entry.item.dueDate:entry.item.date||entry.item.dueDate;return date>=today}).sort((a,b)=>{const ad=a.kind==='event'?a.item.date:a.kind==='task'?a.item.dueDate:a.item.date||a.item.dueDate;const bd=b.kind==='event'?b.item.date:b.kind==='task'?b.item.dueDate:b.item.date||b.item.dueDate;return ad.localeCompare(bd)}).slice(0,60);return `${renderTopBar()}<div class=section><h2>📅 Family Calendar</h2>${adult(S.viewer)?'<button class="btn primary" onclick="openEventForm()">+ Event</button>':''}</div><div class=calendar-toolbar><button class=btn onclick="calendarToday()">Today</button><button class="btn calendar-arrow" aria-label="Previous month" onclick="moveCalendarMonth(-1)">‹</button><h3>${monthStart.toLocaleDateString([],{month:'long',year:'numeric'})}</h3><button class="btn calendar-arrow" aria-label="Next month" onclick="moveCalendarMonth(1)">›</button><div class=calendar-mode><button class="btn ${calendarMode==='month'?'primary':''}" onclick="setCalendarMode('month')">Month</button><button class="btn ${calendarMode==='agenda'?'primary':''}" onclick="setCalendarMode('agenda')">Agenda</button></div></div>${calendarMode==='month'?`<div class=calendar-grid><div class=calendar-weekdays>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(day=>`<span>${day}</span>`).join('')}</div><div class=calendar-days>${dayCells}</div></div><div class=section><h3>${prettyDate(selected)}</h3></div>${selectedItems.map(calendarEntry).join('')||'<div class=card>No calendar items for this day.</div>'}`:`<div class=section><h3>Upcoming</h3></div>${agenda.map(entry=>`<div class=agenda-date><b>${prettyDate(entry.kind==='event'?entry.item.date:entry.kind==='task'?entry.item.dueDate:entry.item.date||entry.item.dueDate,{weekday:'short',month:'short',day:'numeric'})}</b>${calendarEntry(entry)}</div>`).join('')||'<div class=card>No upcoming items.</div>'}`}`}
function selectCalendarDay(key){selectedCalendarDate=key;calendarDate=dateFromKey(key);render('calendar')}
function moveCalendarMonth(amount){calendarDate=new Date(calendarDate.getFullYear(),calendarDate.getMonth()+amount,1);selectedCalendarDate=dateKey(calendarDate);render('calendar')}
function calendarToday(){const today=hubToday();calendarDate=dateFromKey(today);selectedCalendarDate=today;render('calendar')}
function setCalendarMode(mode){calendarMode=mode;render('calendar')}
let danceTab='Dance Home';
function dance(){return `${renderTopBar()}<div class=hero><h1>💃 Dance Hub</h1><p>Practice, sparkle, repeat ✨</p></div><div class=actions>${['Competitions','Schedule','Routines','Costumes','Checklists'].map(c=>`<button class="btn ${danceTab===c?'primary':''}" onclick="danceTab='${c}';render('dance')">${c==='Competitions'?'🏆 ':''}${c}</button>`).join('')}</div><div class=section><h2>${danceTab}</h2><button class=btn onclick="openItem('dance')">+ Add</button></div>${S.dance.filter(d=>d.category===danceTab).map(d=>`<div class="card task"><div class=grow>${d.text}</div><button class=btn onclick="mutate({action:'check',id:${d.id}})">${d.checked?'✅ Ready':'○ To do'}</button></div>`).join('')||'<div class=card>No details yet. Add schedules, venues, routines, or packing notes 🩰</div>'}`}
function tomorrow(){const tomorrowDate=dateFromKey(hubToday());tomorrowDate.setDate(tomorrowDate.getDate()+1);const key=dateKey(tomorrowDate),tasksDue=S.tasks.filter(task=>task.status==='open'&&task.dueDate===key),events=S.events.filter(event=>event.date===key),danceItems=S.dance.filter(item=>(item.date||item.dueDate)===key);return `${renderTopBar()}<div class=hero><h1>🌙 Ready for Tomorrow?</h1><p>${prettyDate(key,{weekday:'long',month:'long',day:'numeric'})}</p></div><div class=actions><button class=btn onclick="render('calendar')">Open calendar</button></div><section class=tomorrow-section><h2>📅 Events</h2>${events.map(event=>calendarEntry({kind:'event',item:event})).join('')||'<p class=meta>No events scheduled.</p>'}</section><section class=tomorrow-section><h2>🎒 School</h2>${[...events.filter(event=>event.category==='School').map(item=>({kind:'event',item})),...tasksDue.filter(task=>task.category==='School').map(item=>({kind:'task',item})),...danceItems.filter(item=>item.category==='School').map(item=>({kind:'dance',item}))].map(calendarEntry).join('')||'<p class=meta>No school items scheduled.</p>'}</section><section class=tomorrow-section><h2>💃 Dance</h2>${danceItems.filter(item=>item.category==='Dance'||item.category==='Schedule'||item.category==='Competitions').map(item=>calendarEntry({kind:'dance',item})).join('')||'<p class=meta>No dance items scheduled.</p>'}</section><section class=tomorrow-section><h2>✅ Tasks & chores due</h2>${tasksDue.map(task=>calendarEntry({kind:'task',item:task})).join('')||'<p class=meta>No tasks due tomorrow.</p>'}</section>`}
const danceSections=['Dance Home','Schedule','Routines','Competitions','Costumes','Dance Checklists'];
const danceChecklistTypes=['Competition Packing','Practice Bag','Costume Checklist','Travel Checklist','Custom'];
const recognitionTypes=['Great Job','Nice Work','Streak Saver','Above & Beyond','Proud of You','Thank You'];
let editingDanceId=null;
let danceRecordFilter='active';
function danceRecords(type){return (S.dance||[]).filter(item=>item.danceType===type&&!item.archived)}
function danceViewRecords(type){return (S.dance||[]).filter(item=>item.danceType===type&&(danceRecordFilter==='all'||(danceRecordFilter==='archived'?item.archived:!item.archived)))}
function danceById(id){return (S.dance||[]).find(item=>item.id===Number(id))}
function danceName(item){return item?.title||item?.text||'Dance item'}
function danceDate(value){return value?prettyDate(value,{weekday:'short',month:'short',day:'numeric',year:'numeric'}):'Date not set'}
function danceChoices(name,items,selected,label){const ids=new Set((selected||[]).map(Number));return `<fieldset class="field dance-choice-list"><legend>${label}</legend>${items.length?items.map(item=>`<label class=check-option><input type=checkbox name="${name}" value="${item.id}" ${ids.has(item.id)?'checked':''}> ${danceName(item)}</label>`).join(''):'<span class=meta>No items yet.</span>'}</fieldset>`}
function danceInput(id,label,value='',type='text'){return `<div class=field><label for=${id}>${label}</label><input id=${id} type=${type} maxlength=4000 value="${value||''}"></div>`}
function danceTextarea(id,label,value='',placeholder=''){return `<div class=field><label for=${id}>${label}</label><textarea id=${id} rows=3 maxlength=4000 placeholder="${placeholder}">${value||''}</textarea></div>`}
function danceCardActions(item){return adult(S.viewer)?`${item.archived?'<span class="dance-kicker archived">Archived</span>':''}<button class=btn onclick="openDanceForm('${item.danceType}',${item.id})">Edit</button>${item.archived?`<button class=btn onclick="mutate({action:'restore',id:${item.id}},'dance')">Restore</button>`:`<button class=btn onclick="mutate({action:'archive',id:${item.id}},'dance')">Archive</button>`}<button class="btn bad" onclick="confirmDanceDelete(${item.id})">Delete</button>`:''}
function danceAddButton(type,label='+ Add'){return adult(S.viewer)?`<button class="btn primary" onclick="openDanceForm('${type}')">${label}</button>`:''}
function danceRoutineNames(ids){return (ids||[]).map(id=>danceName(danceById(id))).join(', ')||'None linked'}
function danceCompetitionNames(ids){return (ids||[]).map(id=>danceName(danceById(id))).join(', ')||'None linked'}
function danceProgress(checklist){const items=checklist.checklistItems||[],done=items.filter(item=>item.checked).length;return {done,total:items.length,percent:items.length?Math.round(done*100/items.length):0}}
function danceChecklistCard(item){const progress=danceProgress(item);return `<article class="card dance-card"><div class=dance-card-head><div><span class="dance-kicker">${item.checklistType||'Dance checklist'}</span><h3>${danceName(item)}</h3></div>${danceCardActions(item)}</div>${item.competitionId?`<p class=meta>🏆 ${danceName(danceById(item.competitionId))}</p>`:''}<div class=dance-progress><span>${progress.done} of ${progress.total} ready</span><progress max=${Math.max(progress.total,1)} value=${progress.done}></progress></div><div class=dance-check-items>${(item.checklistItems||[]).map(check=>`<label class="check-option ${check.checked?'checked':''}"><input type=checkbox ${check.checked?'checked':''} onchange="mutate({action:'checklist_item',id:${item.id},itemId:${check.id}},'dance')"> ${check.text}</label>`).join('')||'<p class=meta>No checklist items yet.</p>'}</div></article>`}
function danceDeadlineRows(){return danceRecords('competition').flatMap(comp=>(comp.deadlines||[]).map(deadline=>({competition:comp,...deadline}))).filter(row=>row.date>=hubToday()).sort((a,b)=>a.date.localeCompare(b.date))}
function danceHomeView(){const today=hubToday(),competitions=danceRecords('competition').filter(item=>item.startDate>=today).sort((a,b)=>a.startDate.localeCompare(b.startDate)),events=(S.events||[]).filter(event=>visible(event)&&event.date>=today&&(event.category==='Dance'||event.category==='Competitions')).sort((a,b)=>`${a.date}${a.startTime||''}`.localeCompare(`${b.date}${b.startTime||''}`)),practices=events.filter(event=>event.category==='Dance'||/practice/i.test(event.title||'')),deadlines=danceDeadlineRows(),costumes=danceRecords('costume').filter(item=>!item.ordered||!item.received||item.alterationsNeeded&&!item.alterationsCompleted),checklists=danceRecords('checklist'),next=competitions[0],nextEvent=events[0],progress=checklists.map(danceProgress),ready=progress.reduce((sum,item)=>sum+item.done,0),total=progress.reduce((sum,item)=>sum+item.total,0);return `<div class=dance-overview><section class="dance-feature ${next?'':'empty'}"><span class=dance-kicker>Next competition</span>${next?`<h2>${next.title}</h2><p>${danceDate(next.startDate)}${next.endDate&&next.endDate!==next.startDate?` – ${danceDate(next.endDate)}`:''}</p><p>${next.schedulePending?'SCHEDULE PENDING':next.performanceSchedule||'Performance schedule available'}</p>${next.venue?`<p>${next.venue}</p>`:''}<button class=btn onclick="openDanceDetails(${next.id})">Competition details</button>`:'<p>No upcoming competitions.</p>'}</section><div class=dance-overview-grid><section class="card dance-summary"><b>Next dance event</b>${nextEvent?`<p>${nextEvent.title}</p><span class=meta>${danceDate(nextEvent.date)}${nextEvent.startTime?' · '+nextEvent.startTime:''}</span>`:'<p class=meta>No upcoming dance event.</p>'}</section><section class="card dance-summary"><b>Upcoming practices</b>${practices.slice(0,3).map(event=>`<p>${event.title} <span class=meta>${danceDate(event.date)}</span></p>`).join('')||'<p class=meta>Nothing scheduled.</p>'}</section><section class="card dance-summary"><b>Upcoming deadlines</b>${deadlines.slice(0,3).map(item=>`<p>${item.title} <span class=meta>${danceDate(item.date)}</span></p>`).join('')||'<p class=meta>No deadlines coming up.</p>'}</section><section class="card dance-summary"><b>Costume attention</b><p>${costumes.length?`${costumes.length} item${costumes.length===1?'':'s'} to check`:'All costume items are on track.'}</p>${costumes.slice(0,2).map(item=>`<span class=meta>${danceName(item)}</span>`).join('<br>')}</section><section class="card dance-summary"><b>Packing progress</b><p>${ready} of ${total} checklist items ready</p>${checklists.slice(0,2).map(item=>`<span class=meta>${danceName(item)} · ${danceProgress(item).done}/${danceProgress(item).total}</span>`).join('<br>')}</section></div>${adult(S.viewer)?`<div class="actions dance-add-actions">${danceAddButton('competition','+ Competition')}${danceAddButton('routine','+ Routine')}${danceAddButton('costume','+ Costume')}${danceAddButton('checklist','+ Checklist')}</div>`:''}</div>`}
function danceAttentionMarkup(){const items=S.danceAttention||[];if(!items.length)return '';return `<section class=dance-attention><div class=dance-attention-heading><div><span class=dance-kicker>Action needed</span><h2>Needs Attention <span>${items.length}</span></h2></div><p>These items are keeping the Dance badge active.</p></div><div class=dance-attention-list>${items.map(item=>`<article class=dance-attention-item><div><b>${item.title}</b><p>${item.reasons.join(' · ')}</p></div><div class=dance-attention-actions><button class=btn onclick="danceTab='${item.target}';render('dance')">View</button>${(item.deadlines||[]).map(deadline=>`<button class="btn good" onclick="markDanceDeadlineDone(${item.id},${escapeText(JSON.stringify(deadline.id))})">Mark done: ${deadline.title}</button>`).join('')}</div></article>`).join('')}</div></section>`}
const danceHomeWithoutAttention=danceHomeView;
danceHomeView=function(){return danceHomeWithoutAttention().replace('<div class=dance-overview>',`<div class=dance-overview>${danceAttentionMarkup()}`)};
function markDanceDeadlineDone(id,deadlineId){return mutate({action:'deadline_done',id,deadlineId},'dance')}
function danceScheduleView(){const today=hubToday(),entries=[...(S.events||[]).filter(event=>visible(event)&&event.date>=today&&(event.category==='Dance'||event.category==='Competitions')).map(item=>({kind:'event',item})),...danceViewRecords('schedule').filter(item=>danceRecordFilter!=='active'||(item.date||item.startDate||'')>=today).map(item=>({kind:'dance',item})),...danceViewRecords('costume').filter(item=>danceRecordFilter!=='active'||item.neededBy>=today).map(item=>({kind:'dance',item}))].sort((a,b)=>String(a.item.date||a.item.startDate||a.item.neededBy).localeCompare(String(b.item.date||b.item.startDate||b.item.neededBy)));return `<section class= dance-list>${entries.map(entry=>entry.kind==='event'?calendarEntry(entry):`<button class="calendar-entry dance" onclick="openDanceDetails(${entry.item.id})"><span class=calendar-entry-type>${entry.item.danceType==='costume'?'Costume deadline':'Dance schedule'}</span><b>${danceName(entry.item)}</b><span>${danceDate(entry.item.date||entry.item.startDate||entry.item.neededBy)}${entry.item.time?' · '+entry.item.time:''}</span></button>`).join('')||'<div class=card>No dance dates are scheduled.</div>'}</section>${danceAddButton('schedule','+ Schedule item')}`}
function danceRoutineView(){const routines=danceViewRecords('routine');return `<div class=dance-list>${routines.map(item=>`<article class="card dance-card"><div class=dance-card-head><div><span class=dance-kicker>${item.routineType||'Routine'}</span><h3>${danceName(item)}</h3></div>${danceCardActions(item)}</div><p>${item.choreographer?`Choreographer: ${item.choreographer}`:''}${item.instructor?`${item.choreographer?' · ':''}Instructor: ${item.instructor}`:''}</p><p class=meta>Competitions: ${danceCompetitionNames(item.competitionIds)}${item.costumeId?` · Costume: ${danceName(danceById(item.costumeId))}`:''}</p>${item.scheduleInformation?`<p>${item.scheduleInformation}</p>`:''}${item.notes?`<p>${item.notes}</p>`:''}</article>`).join('')||'<div class=card>No routines yet.</div>'}</div>${danceAddButton('routine','+ Routine')}`}
function danceCompetitionView(){const comps=danceViewRecords('competition').sort((a,b)=>String(a.startDate||'').localeCompare(String(b.startDate||'')));return `<div class=dance-list>${comps.map(item=>`<article class="card dance-card competition-card"><div class=dance-card-head><div><span class="dance-kicker ${item.schedulePending?'pending':''}">${item.schedulePending?'SCHEDULE PENDING':'Competition'}</span><h3>${danceName(item)}</h3></div>${danceCardActions(item)}</div><p>${danceDate(item.startDate)}${item.endDate&&item.endDate!==item.startDate?` – ${danceDate(item.endDate)}`:''}</p><p>${[item.venue,item.address].filter(Boolean).join(' · ')||'Venue not set'}</p>${item.arrivalTime?`<p>Arrival ${item.arrivalTime}${item.callTime?` · Call ${item.callTime}`:''}</p>`:''}${item.performanceSchedule?`<p>${item.performanceSchedule}</p>`:''}<p class=meta>Routines: ${danceRoutineNames(item.routineIds)} · Costumes: ${danceRoutineNames(item.costumeIds)}</p>${item.deadlines?.length?`<p class=meta>Deadlines: ${item.deadlines.map(deadline=>`${deadline.title} · ${danceDate(deadline.date)}`).join(' / ')}</p>`:''}${item.results?`<p>Results: ${item.results}</p>`:''}${item.awards?`<p>Awards: ${item.awards}</p>`:''}${danceCardActions(item)?`<button class=btn onclick="openDanceDetails(${item.id})">Full details</button>`:`<button class=btn onclick="openDanceDetails(${item.id})">Details</button>`}</article>`).join('')||'<div class=card>No competitions yet.</div>'}</div>${danceAddButton('competition','+ Competition')}`}
function confirmDanceDelete(id){const item=danceById(id);if(!adult(S.viewer)||!item?.danceType)return;modal(`<h2>Delete ${danceName(item)}?</h2><p>This removes the Dance record and its generated calendar entries. Other Dance records are kept, with links to this record cleared.</p><div class=actions><button class=btn onclick="openDanceForm('${item.danceType}',${item.id})">Cancel</button><button class="btn bad" onclick="mutate({action:'delete',id:${item.id}},'dance')">Delete</button></div>`) }
function confirmArchiveSeason(){if(!adult(S.viewer))return;const count=(S.dance||[]).filter(item=>!item.archived).length;if(!count)return alert('No active Dance records to archive');modal(`<h2>Archive Dance season?</h2><p>This archives ${count} active Dance record${count===1?'':'s'} (competitions, routines, costumes, schedule items and checklists). They leave the active Dance views, calendar and reminders, and stay in Archived. Nothing is deleted.</p><div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('dance')">Cancel</button><button class="btn primary" onclick="mutate({action:'archive_season'},'dance')">Archive season</button></div>`)}
function danceCostumeView(){const items=danceViewRecords('costume');return `<div class=dance-list>${items.map(item=>{const status=item.alterationsNeeded&&!item.alterationsCompleted?'Alterations needed':!item.ordered?'Not ordered':!item.received?'Ordered · waiting':'Ready';const tone=status==='Ready'?'ready':status==='Alterations needed'?'attention':'pending';return `<article class="card dance-card"><div class=dance-card-head><div><span class="dance-kicker ${tone}">${status}</span><h3>${danceName(item)}</h3></div>${danceCardActions(item)}</div><p>Routine: ${danceRoutineNames(item.routineIds)}</p>${item.neededBy?`<p class=meta>Needed by ${danceDate(item.neededBy)}</p>`:''}${item.accessories?`<p>Accessories: ${item.accessories}</p>`:''}${item.shoes?`<p>Shoes: ${item.shoes}</p>`:''}${item.tights?`<p>Tights: ${item.tights}</p>`:''}${item.notes?`<p>${item.notes}</p>`:''}</article>`}).join('')||'<div class=card>No costume items yet.</div>'}</div>${danceAddButton('costume','+ Costume')}`}
function danceChecklistView(){return `<div class=dance-list>${danceViewRecords('checklist').map(danceChecklistCard).join('')||'<div class=card>No dance checklists yet.</div>'}</div>${danceAddButton('checklist','+ Checklist')}`}
function dance(){const views={'Dance Home':danceHomeView,'Schedule':danceScheduleView,'Routines':danceRoutineView,'Competitions':danceCompetitionView,'Costumes':danceCostumeView,'Dance Checklists':danceChecklistView},hasFilter=danceTab!=='Dance Home';return `${renderTopBar()}<header class="dance-heading"><div><span class=dance-kicker>Arielle's dance season</span><h1>💃 Dance Hub</h1></div>${adult(S.viewer)?`<button class=btn onclick="confirmArchiveSeason()">Archive season</button>`:''}</header><nav class=dance-nav aria-label="Dance Hub">${danceSections.map(section=>`<button class="btn ${danceTab===section?'primary':''}" onclick="danceTab='${section}';render('dance')">${section}</button>`).join('')}</nav>${hasFilter?`<div class="dance-record-filter" role=group aria-label="Dance record status">${[['active','Active'],['archived','Archived'],['all','All']].map(([value,label])=>`<button class="btn ${danceRecordFilter===value?'primary':''}" aria-pressed="${danceRecordFilter===value}" onclick="danceRecordFilter='${value}';render('dance')">${label}</button>`).join('')}</div>`:''}<main class=dance-content>${views[danceTab]?.()||danceHomeView()}</main>`}
function openDanceForm(type,id=null){if(!adult(S.viewer))return;const item=id?danceById(id):null;if(id&&!item)return;editingDanceId=item?.id||null;const selected=(key)=>item?.[key]||[];let fields=`${danceInput('danceTitle',type==='routine'?'Routine name':type==='competition'?'Competition name':type==='costume'?'Costume name':'Name',item?.title||'')}`;
 if(type==='routine')fields+=`<div class=field><label for=danceRoutineType>Routine type</label><select id=danceRoutineType>${['Solo','Trio','Group'].map(value=>`<option ${item?.routineType===value?'selected':''}>${value}</option>`).join('')}</select></div>${danceInput('danceChoreographer','Choreographer',item?.choreographer)}${danceInput('danceInstructor','Instructor',item?.instructor)}${danceChoices('dance-competitionIds',danceRecords('competition'),selected('competitionIds'),'Associated competitions')}<div class=field><label for=danceCostumeId>Costume</label><select id=danceCostumeId><option value="">No costume linked</option>${danceRecords('costume').map(costume=>`<option value=${costume.id} ${Number(item?.costumeId)===costume.id?'selected':''}>${danceName(costume)}</option>`).join('')}</select></div>${danceTextarea('danceScheduleInformation','Schedule information',item?.scheduleInformation)}${danceTextarea('danceNotes','Notes',item?.notes)}`;
 if(type==='competition')fields+=`${danceInput('danceStartDate','Start date',item?.startDate,'date')}${danceInput('danceEndDate','End date',item?.endDate,'date')}${danceInput('danceVenue','Venue',item?.venue)}${danceInput('danceAddress','Location / address',item?.address)}${danceInput('danceHotel','Hotel',item?.hotel)}${danceTextarea('danceTravel','Travel information',item?.travel)}<div class=row>${danceInput('danceArrivalTime','Arrival time',item?.arrivalTime,'time')}${danceInput('danceCallTime','Call time',item?.callTime,'time')}</div>${danceTextarea('dancePerformanceSchedule','Performance schedule',item?.performanceSchedule)}<label class="toggle"><input id=danceSchedulePending type=checkbox ${item?.schedulePending!==false?'checked':''}> SCHEDULE PENDING</label>${danceChoices('dance-routineIds',danceRecords('routine'),selected('routineIds'),'Associated routines')}${danceChoices('dance-costumeIds',danceRecords('costume'),selected('costumeIds'),'Associated costumes')}${danceTextarea('danceDeadlines','Deadlines · one per line: name|YYYY-MM-DD',(item?.deadlines||[]).map(deadline=>`${deadline.title}|${deadline.date}`).join('\n'))}${adult(S.viewer)?danceTextarea('danceFees','Adult-only fees · one per line: label|amount',(item?.fees||[]).map(fee=>`${fee.label}|${fee.amount??''}`).join('\n')):''}${danceTextarea('danceResults','Results',item?.results)}${danceTextarea('danceAwards','Awards',item?.awards)}${danceTextarea('danceNotes','Notes',item?.notes)}`;
 if(type==='costume')fields+=`${danceChoices('dance-routineIds',danceRecords('routine'),selected('routineIds'),'Associated routines')}<div class="dance-status-grid"><label class=check-option><input id=danceOrdered type=checkbox ${item?.ordered?'checked':''}> Ordered</label><label class=check-option><input id=danceReceived type=checkbox ${item?.received?'checked':''}> Received</label><label class=check-option><input id=danceAlterationsNeeded type=checkbox ${item?.alterationsNeeded?'checked':''}> Alterations needed</label><label class=check-option><input id=danceAlterationsCompleted type=checkbox ${item?.alterationsCompleted?'checked':''}> Alterations completed</label></div>${danceInput('danceNeededBy','Date needed',item?.neededBy,'date')}${danceTextarea('danceAccessories','Accessories',item?.accessories)}${danceInput('danceShoes','Shoes',item?.shoes)}${danceInput('danceTights','Tights',item?.tights)}${danceTextarea('danceNotes','Notes',item?.notes)}`;
 if(type==='checklist')fields+=`<div class=field><label for=danceChecklistType>Checklist type</label><select id=danceChecklistType>${danceChecklistTypes.map(value=>`<option ${item?.checklistType===value?'selected':''}>${value}</option>`).join('')}</select></div>${danceChoices('dance-competitionIds',danceRecords('competition'),item?.competitionId?[item.competitionId]:[],'Associated competition')}${danceInput('danceDate','Date (optional)',item?.date,'date')}${danceTextarea('danceChecklistItems','Checklist items · one per line',(item?.checklistItems||[]).map(entry=>entry.text).join('\n'),'Costume, shoes, tights, hair supplies…')}`;
 if(type==='schedule')fields+=`${danceInput('danceDate','Date',item?.date||item?.startDate,'date')}${danceInput('danceTime','Time',item?.time,'time')}${danceTextarea('danceNotes','Details',item?.notes)}`;
 modal(`<h2>${item?'Edit':'Add'} ${type==='routine'?'routine':type==='competition'?'competition':type==='costume'?'costume item':type==='checklist'?'dance checklist':'dance schedule item'}</h2>${fields}<div class=actions><button class=btn onclick="document.getElementById('modal').remove();render('dance')">Cancel</button><button class="btn primary" onclick="saveDanceForm('${type}')">${item?'Save changes':'Save'}</button></div>${item?`<div class="actions dance-lifecycle-actions">${item.archived?`<button class="btn good" onclick="mutate({action:'restore',id:${item.id}},'dance')">Restore</button>`:`<button class=btn onclick="mutate({action:'archive',id:${item.id}},'dance')">Archive</button>`}<button class="btn bad" onclick="confirmDanceDelete(${item.id})">Delete</button></div>`:''}`) }
function danceChecked(name){return [...document.querySelectorAll(`[name="${name}"]:checked`)].map(input=>Number(input.value))}
function danceLines(id){return (document.getElementById(id)?.value||'').split(/\r?\n/).map(line=>line.trim()).filter(Boolean)}
async function saveDanceForm(type){const id=editingDanceId,item=id?danceById(id):null,title=val('danceTitle'),record={title,danceType:type,visibility:'Family'};if(type==='routine')Object.assign(record,{routineType:val('danceRoutineType'),choreographer:val('danceChoreographer'),instructor:val('danceInstructor'),competitionIds:danceChecked('dance-competitionIds'),costumeId:Number(val('danceCostumeId'))||null,scheduleInformation:val('danceScheduleInformation'),notes:val('danceNotes')});if(type==='competition'){const oldDeadlines=item?.deadlines||[];record.startDate=val('danceStartDate');record.endDate=val('danceEndDate');record.venue=val('danceVenue');record.address=val('danceAddress');record.hotel=val('danceHotel');record.travel=val('danceTravel');record.arrivalTime=val('danceArrivalTime');record.callTime=val('danceCallTime');record.performanceSchedule=val('dancePerformanceSchedule');record.schedulePending=document.getElementById('danceSchedulePending').checked;record.routineIds=danceChecked('dance-routineIds');record.costumeIds=danceChecked('dance-costumeIds');record.deadlines=danceLines('danceDeadlines').map((line,index)=>{const [name,date]=line.split('|').map(value=>value.trim());return {id:oldDeadlines[index]?.id||String(index+1),title:name,date,completed:!!oldDeadlines[index]?.completed}});record.fees=danceLines('danceFees').map(line=>{const [label,amount]=line.split('|').map(value=>value.trim());return {label,amount:amount||''}});record.results=val('danceResults');record.awards=val('danceAwards');record.notes=val('danceNotes')}if(type==='costume')Object.assign(record,{routineIds:danceChecked('dance-routineIds'),ordered:document.getElementById('danceOrdered').checked,received:document.getElementById('danceReceived').checked,alterationsNeeded:document.getElementById('danceAlterationsNeeded').checked,alterationsCompleted:document.getElementById('danceAlterationsCompleted').checked,neededBy:val('danceNeededBy'),accessories:val('danceAccessories'),shoes:val('danceShoes'),tights:val('danceTights'),notes:val('danceNotes')});if(type==='checklist'){const previous=item?.checklistItems||[];record.checklistType=val('danceChecklistType');record.competitionId=danceChecked('dance-competitionIds')[0]||null;record.date=val('danceDate');record.checklistItems=danceLines('danceChecklistItems').map((text,index)=>({text,checked:previous[index]?.text===text&&previous[index].checked||false}))}if(type==='schedule')Object.assign(record,{date:val('danceDate'),time:val('danceTime'),notes:val('danceNotes')});const result=await mutate(id?{action:'edit',id,record}:{action:'create',kind:'dance',record},'dance');if(result)editingDanceId=null;return result}
function openDanceDetails(id){const item=danceById(id);if(!item)return;const relations=item.danceType==='routine'?`<p>Competitions: ${danceCompetitionNames(item.competitionIds)}</p><p>Costume: ${item.costumeId?danceName(danceById(item.costumeId)):'None linked'}</p>`:item.danceType==='costume'?`<p>Routines: ${danceRoutineNames(item.routineIds)}</p>`:item.danceType==='competition'?`<p>Routines: ${danceRoutineNames(item.routineIds)}</p><p>Costumes: ${danceRoutineNames(item.costumeIds)}</p>`:'';const finance=adult(S.viewer)?`<p>Fees: ${(item.fees||[]).map(fee=>`${fee.label} ${fee.amount??''}`).join(', ')||'None listed'}</p>`:'';modal(`<h2>${danceName(item)}</h2><dl class=task-details>${detailRow('Type',item.danceType)}${detailRow('Date',danceDate(item.startDate||item.date||item.neededBy))}${detailRow('End date',item.endDate?danceDate(item.endDate):'')}${detailRow('Status',item.danceType==='competition'&&item.schedulePending?'SCHEDULE PENDING':'')}${detailRow('Venue',item.venue)}${detailRow('Address',item.address)}${detailRow('Hotel',item.hotel)}${detailRow('Arrival / call',`${item.arrivalTime||''}${item.callTime?' / '+item.callTime:''}`)}${detailRow('Performance schedule',item.performanceSchedule)}${detailRow('Notes',item.notes)}${detailRow('Accessories',item.accessories)}${detailRow('Shoes / tights',[item.shoes,item.tights].filter(Boolean).join(' / '))}</dl>${relations}${item.deadlines?.length?`<h3>Deadlines</h3>${item.deadlines.map(deadline=>`<p>${deadline.title} · ${danceDate(deadline.date)}</p>`).join('')}`:''}${item.checklistItems?danceChecklistCard(item):''}${finance}<div class=actions>${adult(S.viewer)?`<button class=btn onclick="openDanceForm('${item.danceType}',${item.id})">Edit</button>`:''}<button class=btn onclick="document.getElementById('modal').remove();render('dance')">Close</button></div>`)}
const showDanceDetails=openDanceDetails;
openDanceDetails=showDanceDetails;
function recognitionForm(taskId){const task=taskById(taskId);if(!adult(S.viewer)||!task||task.status!=='done'||task.completedBy!=='Daughter')return;modal(`<h2>🌟 Recognize ${displayName('Daughter')}</h2><p>${task.title}</p><div class=field><label for=recognitionType>Recognition</label><select id=recognitionType>${recognitionTypes.map(value=>`<option>${value}</option>`).join('')}</select></div>${danceTextarea('recognitionMessage','A note (optional)')}<div class=actions><button class=btn onclick="openTaskDetails(${task.id})">Cancel</button><button class="btn primary" onclick="sendRecognition(${task.id})">Give recognition</button></div>`)}
