const reminderTypes={task_due:'Task due',priority:'Priority task',overdue:'Overdue',urgent_ack:'Urgent acknowledgement',event_upcoming:'Upcoming event',dance_upcoming:'Dance deadline',task_assigned:'New task assigned',task_acknowledgement:'Acknowledgement needed',task_update:'Task update',request_update:'Request update',board_update:'Family Board update',dance_update:'Dance update',calendar_update:'Calendar update',list_update:'Shared List update',weekly_recap:'Weekly Recap'};
async function reminderAction(id,action){const restore=pendingButton();try{await api('reminders/action',{id,action});await refresh(true)}catch(error){alert(error.message)}finally{restore()}}
async function clearReadReminders(){const restore=pendingButton();try{await api('reminders/action',{action:'clear_read'});await refresh(true)}catch(error){alert(error.message)}finally{restore()}}
function openReminder(id){const reminder=S.reminders.find(item=>item.id===Number(id));if(!reminder)return;reminderAction(reminder.id,'read');if(reminder.sourceKind==='tasks')openTaskDetails(reminder.sourceId);else if(reminder.sourceKind==='events')openEventDetails(reminder.sourceId);else if(reminder.sourceKind==='dance')openDanceDetails(reminder.sourceId)}
function reminderCard(reminder){return `<article class="card reminder-card ${reminder.read?'read':''} ${reminder.type==='urgent_ack'?'urgent-reminder':''}"><button class=reminder-open onclick="openReminder(${reminder.id})"><span class=reminder-type>${reminderTypes[reminder.type]||'Reminder'}${reminder.priority?` · ${reminder.priority}`:''}</span><b>${reminder.title}</b><span>${reminder.date?prettyDate(reminder.date,{weekday:'short',month:'short',day:'numeric'}):''}${reminder.time?' · '+reminder.time:''}</span><time>${timeLabel(reminder.dueAt)}</time></button><div class=actions>${reminder.read?'<span class=meta>Read</span>':`<button class=btn onclick="reminderAction(${reminder.id},'read')">Mark read</button>`}<button class="btn bad" onclick="reminderAction(${reminder.id},'dismiss')">Dismiss</button></div></article>`}
function reminders(){const active=(S.reminders||[]).filter(reminder=>!reminder.dismissed),readCount=(S.reminders||[]).filter(reminder=>reminder.read||reminder.dismissed).length;return `${renderTopBar()}<div class=section><h2>🔔 Reminders</h2>${readCount?'<button class=btn onclick="clearReadReminders()">Clear read</button>':''}</div><p class=meta>Due items, upcoming events, and acknowledgement reminders.</p>${active.map(reminderCard).join('')||'<div class=card>No active reminders.</div>'}`}
function privacy(){if(!adult(S.viewer))return `${renderTopBar()}<div class=hero><h1>🔐 Our Family Privacy</h1><p>Family information is protected by the server.</p></div><section class="privacy-levels"><h2>Who can see each kind of information</h2><div class=privacy-level><b>Family / Everyone</b><span>Jermaine, Stephanie, and Arielle</span></div><div class=privacy-level><b>Adults Only</b><span>Jermaine and Stephanie</span></div><div class=privacy-level><b>Assigned Person</b><span>The selected family member</span></div><div class=privacy-level><b>Me Only</b><span>Only the person who created the entry</span></div><p class=meta>Vault, personal notes, reminders, activity, and badges follow the same server-side access rules.</p></section><section class=privacy-chatgpt><h2>🤖 ChatGPT Access</h2><p><b>Default:</b> restricted, read-only access to appropriate tasks and upcoming family events only.</p><p>Blocked: location, Adult Vault, Me Only, financial information, documents, security information, and sensitive information about Arielle.</p><p class=meta>No unrestricted ChatGPT access is configured.</p></section>`;const accounts=[['Dad',displayName('Dad'),'Adult / Admin'],['Mom',displayName('Mom'),'Adult / Admin'],['Daughter',displayName('Daughter'),'Child / Family Member']],areas=[['Family Calendar',['Family','Family','Family']],['Tasks / Chores',['Family / Adults / Assigned / Me','Family / Adults / Assigned / Me','Family / Assigned']],['Family Board',['Family','Family','Family']],['Ask Parents',['Family','Family','Family']],['Shared Lists',['Family','Family','Family']],['Dance Hub',['Family','Family','Family']],['Weekly Recap',['Authorized records only','Authorized records only','Arielle authorized records']],['Adult Vault',['Shared Adult Vault','Shared Adult Vault','Blocked']],['Me Only',['Jermaine only','Stephanie only','Arielle only']],['Financial / Dance financial information',['Jermaine and Stephanie','Jermaine and Stephanie','Blocked']]];return `${renderTopBar()}<div class=hero><h1>🔐 Access & Privacy</h1><p>Access boundaries for the three family accounts</p></div><section class=privacy-accounts><h2>Family accounts</h2>${accounts.map(([id,name,role])=>`<div class=privacy-account><b>${name}</b><span>${role}</span></div>`).join('')}</section><section class=privacy-matrix><h2>Area access</h2><div class=privacy-matrix-head><b>Area</b>${accounts.map(([,name])=>`<b>${name}</b>`).join('')}</div>${areas.map(([area,...access])=>`<div class=privacy-matrix-row><b>${area}</b>${access.map(value=>`<span>${value}</span>`).join('')}</div>`).join('')}<p class=meta>Entries and activity details are not shown here. The server enforces these access rules before sending data.</p></section><section class=privacy-chatgpt><h2>🤖 ChatGPT Access</h2><p><b>Default:</b> restricted, read-only access to appropriate tasks and upcoming family events only.</p><p>Blocked: location, Adult Vault, Me Only, financial information, documents, security information, and sensitive information about Arielle.</p><p class=meta>No unrestricted ChatGPT access is configured.</p></section>`}
